// --- SLOTS & ORDERS ---

// Ensure a slot document exists
export const ensureSlotExists = async (slotId: string, startTime: Date) => {
  try {
    const slotRef = doc(db, 'timeSlots', slotId);
    await setDoc(slotRef, {
      id: slotId,
      startTime: Timestamp.fromDate(startTime),
      maxOrders: MAX_ORDERS_PER_SLOT,
    }, { merge: true });
  } catch (e) {
    console.error("Failed to ensure slot exists", e);
  }
};

export const createOrder = async (
  userId: string, 
  userEmail: string, 
  items: MenuItem[], 
  quantities: Record<string, number>,
  slotId: string,
  slotDate: Date,
  transactionId: string,
  customerName: string,
  customerMobile: string
): Promise<string> => {

  const totalAmount = items.reduce((sum, item) => sum + (item.price * quantities[item.id]), 0);
  const orderItems = items.map(item => ({
    menuItemId: item.id,
    name: item.name,
    price: item.price,
    quantity: quantities[item.id]
  }));

  // Client-side integrity checks before transaction
  if (totalAmount <= 0) throw new Error("Order amount must be positive");
  if (items.length === 0) throw new Error("Order must contain items");
  if (slotDate < new Date(Date.now() - 5 * 60 * 1000)) throw new Error("Cannot book past time slots"); // allow 5 min clock skew

  try {
    const orderId = await runTransaction(db, async (transaction) => {
      const slotRef = doc(db, 'timeSlots', slotId);
      const slotDoc = await transaction.get(slotRef);

      let currentOrders = 0;
      let maxOrders = MAX_ORDERS_PER_SLOT;
      let status = 'available';

      if (slotDoc.exists()) {
        const slotData = slotDoc.data() as TimeSlot;
        currentOrders = slotData.currentOrders || 0;
        maxOrders = slotData.maxOrders;
        status = slotData.status;
      }

      if (status !== 'available' || currentOrders >= maxOrders) {
        throw new Error("SLOT_FULL");
      }

      // Create or Update Slot
      transaction.set(slotRef, {
        id: slotId,
        startTime: Timestamp.fromDate(slotDate),
        maxOrders,
        currentOrders: currentOrders + 1,
        status: (currentOrders + 1 >= maxOrders) ? 'full' : 'available'
      }, { merge: true });

      // Create Order
      const newOrderRef = doc(collection(db, 'orders'));
      const newOrder: Omit<Order, 'id'> = {
        userId,
        userEmail,
        customerName,
        customerMobile,
        items: orderItems,
        totalAmount,
        status: OrderStatus.PENDING, // Security: Must start as PENDING or CONFIRMED as per rules
        scheduledTime: Timestamp.fromDate(slotDate),
        slotId,
        transactionId,
        createdAt: Timestamp.now()
      };

      transaction.set(newOrderRef, newOrder);
      return newOrderRef.id;
    });
    return orderId;
  } catch (e) {
    console.error("Transaction failed: ", e);
    throw e;
  }
};

// --- USER ORDERS ---
export const subscribeToUserOrders = (userId: string, callback: (orders: Order[]) => void) => {
  const q = query(
    collection(db, 'orders'), 
    where('userId', '==', userId)
  );

  return onSnapshot(q, (snapshot) => {
    const orders = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as Order));
    orders.sort((a, b) => {
       const tA = a.createdAt?.toMillis() || 0;
       const tB = b.createdAt?.toMillis() || 0;
       return tB - tA; // Descending
    });
    callback(orders);
  }, (error) => {
    console.error("Order subscription failed", error);
    callback([]);
  });
};

// --- ADMIN ---
export const subscribeToAllOrders = (callback: (orders: Order[]) => void) => {
  const q = query(collection(db, 'orders'));

  return onSnapshot(q, (snapshot) => {
    const orders = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as Order));
    orders.sort((a, b) => {
       const tA = a.createdAt?.toMillis() || 0;
       const tB = b.createdAt?.toMillis() || 0;
       return tB - tA; // Descending
    });
    callback(orders);
  }, (error) => {
    console.error("Admin subscription failed", error);
    callback([]);
  });
};

