  try {
    const q = query(collection(db, 'menuItems'));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(d => ({ id: d.id, ...d.data() } as MenuItem));
  } catch (error) {
    console.error("Admin menu fetch failed", error);
