  });

  useEffect(() => {
    if (!isAdmin) return;
    const unsubscribe = subscribeToAllOrders((data) => {
      setOrders(data);
    });
    return () => unsubscribe();
  }, [isAdmin]);

  // Load inventory when switching to inventory view
  useEffect(() => {
    if (currentView === 'inventory' && isAdmin) {
      loadInventory();
    }
  }, [currentView, isAdmin]);

  const loadInventory = async () => {
    setIsInventoryLoading(true);
    try {
      const items = await getAllMenuItemsAdmin();
      setMenuItems(items);
    } catch (e) {
      console.error("Failed to load inventory", e);
    } finally {
      setIsInventoryLoading(false);
    }
  };

  if (!user || !isAdmin) return <Navigate to={ROUTES.HOME} replace />;

  // --- ORDER HANDLERS ---
  const handleStatusUpdate = async (orderId: string, newStatus: OrderStatus) => {
    try {
      await updateOrderStatus(orderId, newStatus);
    } catch (e) {
      console.error("Failed to update status", e);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(text);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleToggleStore = async () => {
    setIsTogglingStore(true);
    try {
      await setStoreOpen(!isStoreOpen);
    } catch (error: any) {
      console.error("Failed to toggle store", error);
      alert(`Error updating store status: ${error.message || 'Unknown error'}. Check your internet or permissions.`);
    } finally {
      setIsTogglingStore(false);
    }
  };

  // --- INVENTORY HANDLERS ---
  const handleToggleAvailability = async (item: MenuItem) => {
    try {
      // Optimistic update
      setMenuItems(prev => prev.map(i => i.id === item.id ? { ...i, isAvailable: !i.isAvailable } : i));
      await updateMenuItem(item.id, { isAvailable: !item.isAvailable });
    } catch (e) {
      console.error("Failed to update item availability", e);
      // Revert on failure
      loadInventory();
      alert("Failed to update item.");
    }
  };

  const startEditing = (item: MenuItem) => {
    setEditingItemId(item.id);
    setEditPrice(item.price.toString());
  };

  const savePriceEdit = async (id: string) => {
    const newPrice = parseFloat(editPrice);
    if (isNaN(newPrice) || newPrice <= 0) {
      alert("Please enter a valid price");
      return;
    }
    try {
      await updateMenuItem(id, { price: newPrice });
      setMenuItems(prev => prev.map(i => i.id === id ? { ...i, price: newPrice } : i));
      setEditingItemId(null);
    } catch (e) {
      alert("Failed to update price");
    }
  };

  const handleDeleteItem = async (id: string) => {
    if (!window.confirm("Are you sure you want to delete this item? This cannot be undone.")) return;
    try {
      await deleteMenuItem(id);
      setMenuItems(prev => prev.filter(i => i.id !== id));
    } catch (e) {
      alert("Failed to delete item");
    }
  };

  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addMenuItem({
        name: newItem.name,
        description: newItem.description,
        price: parseFloat(newItem.price),
        category: newItem.category,
        imageUrl: newItem.imageUrl || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c',
        preparationTime: parseInt(newItem.preparationTime),
        isAvailable: newItem.isAvailable
      });
      setIsAddingItem(false);
      setNewItem({
        name: '', description: '', price: '', category: ProductCategory.Snacks, 
        imageUrl: '', preparationTime: '10', isAvailable: true
      });
      loadInventory();
    } catch (error: any) {
      alert("Failed to add item: " + error.message);
    }
  };

  const activeOrders = orders.filter(o => [OrderStatus.PENDING, OrderStatus.CONFIRMED, OrderStatus.PREPARING, OrderStatus.READY].includes(o.status));
  const completedOrders = orders.filter(o => [OrderStatus.COMPLETED, OrderStatus.CANCELLED].includes(o.status));
  const displayOrders = activeOrderTab === 'active' ? activeOrders : completedOrders;

  return (
    <div className="space-y-8 pb-20">
      {/* HEADER AREA */}
      <div className="flex flex-col xl:flex-row xl:items-end justify-between gap-6 border-b border-white pb-8">
        <div>
           <h1 className="text-4xl font-serif font-bold text-white animate-fade-in">Command Center</h1>
           <p className="text-gray-400 mt-2 text-sm">Manage orders, inventory, and store status.</p>
        </div>

        <div className="flex flex-wrap gap-4">
          <button
            onClick={() => setCurrentView('orders')}
            className={`px-6 py-3 text-sm font-bold uppercase tracking-widest transition-all ${currentView === 'orders' ? 'bg-white text-black' : 'bg-gray-900 text-gray-400 hover:text-white'}`}
          >
            Orders
          </button>

          <button
            onClick={() => setCurrentView('inventory')}
            className={`flex items-center gap-2 px-6 py-3 text-sm font-bold uppercase tracking-widest transition-all ${currentView === 'inventory' ? 'bg-white text-black' : 'bg-gray-900 text-gray-400 hover:text-white'}`}
          >
            <Package className="w-4 h-4" /> Inventory
          </button>

          {/* Store Controls */}
          <button 
            onClick={handleToggleStore}
            disabled={isTogglingStore}
            className={`flex items-center gap-3 px-6 py-3 text-sm font-bold uppercase tracking-widest border transition-all duration-300 ${
              isStoreOpen 
                ? 'bg-green-500 text-black border-green-500 hover:bg-green-400' 
                : 'bg-red-900 text-white border-red-900 hover:bg-red-800'
            }`}
          >
            {isTogglingStore ? <Loader2 className="w-4 h-4 animate-spin" /> : <Power className="w-4 h-4" />}
            {isStoreOpen ? 'Online' : 'Offline'}
          </button>
        </div>
      </div>

      {/* --- INVENTORY VIEW --- */}
      {currentView === 'inventory' && (
        <div className="animate-fade-in space-y-8">

          {/* Add Item Button */}
          {!isAddingItem ? (
            <button 
              onClick={() => setIsAddingItem(true)}
              className="w-full border border-dashed border-gray-700 p-8 text-gray-500 hover:text-white hover:border-white transition-colors flex flex-col items-center justify-center gap-2"
            >
              <Plus className="w-8 h-8" />
              <span className="text-sm font-bold uppercase tracking-widest">Add New Menu Item</span>
            </button>
          ) : (
             <form onSubmit={handleAddItem} className="bg-gray-900 border border-gray-800 p-6 space-y-4">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-white font-bold uppercase tracking-widest">Add New Item</h3>
                  <button type="button" onClick={() => setIsAddingItem(false)}><X className="text-gray-400 hover:text-white" /></button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   <input required placeholder="Item Name" value={newItem.name} onChange={e => setNewItem({...newItem, name: e.target.value})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white" />
                   <input required type="number" step="0.01" placeholder="Price" value={newItem.price} onChange={e => setNewItem({...newItem, price: e.target.value})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white" />
                   <select value={newItem.category} onChange={e => setNewItem({...newItem, category: e.target.value as ProductCategory})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white">
                      {Object.values(ProductCategory).map(c => <option key={c} value={c}>{c}</option>)}
                   </select>
                   <input type="number" placeholder="Prep Time (mins)" value={newItem.preparationTime} onChange={e => setNewItem({...newItem, preparationTime: e.target.value})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white" />
                   <input placeholder="Image URL" value={newItem.imageUrl} onChange={e => setNewItem({...newItem, imageUrl: e.target.value})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white md:col-span-2" />
                   <textarea placeholder="Description" value={newItem.description} onChange={e => setNewItem({...newItem, description: e.target.value})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white md:col-span-2 h-24" />
                </div>
                <button type="submit" className="w-full bg-white text-black py-3 font-bold uppercase tracking-widest hover:bg-gray-200">Save Item</button>
             </form>
          )}

          {/* Inventory List */}
          {isInventoryLoading ? (
            <div className="text-center py-12"><Loader2 className="animate-spin w-8 h-8 text-white mx-auto" /></div>
          ) : (
            <div className="grid grid-cols-1 gap-4">
              {menuItems.map(item => (
                <div key={item.id} className={`flex flex-col md:flex-row items-center gap-6 p-4 bg-black border ${item.isAvailable ? 'border-gray-800' : 'border-red-900/50 bg-red-900/10'}`}>
                  <div className="w-16 h-16 bg-gray-900 flex-shrink-0">
                    <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
                  </div>

                  <div className="flex-grow text-center md:text-left">
                    <h3 className="text-white font-bold">{item.name}</h3>
                    <span className="text-xs text-gray-500 uppercase tracking-wider">{item.category}</span>
                  </div>

                  {/* Price Editor */}
                  <div className="flex items-center gap-2">
                    {editingItemId === item.id ? (
                      <div className="flex items-center">
                        <input 
                          type="number" 
                          value={editPrice} 
                          onChange={(e) => setEditPrice(e.target.value)}
                          className="w-20 bg-gray-900 border border-white p-1 text-white text-sm"
                          autoFocus
                        />
                        <button onClick={() => savePriceEdit(item.id)} className="p-2 text-green-500 hover:text-green-400"><Save className="w-4 h-4" /></button>
                        <button onClick={() => setEditingItemId(null)} className="p-2 text-red-500 hover:text-red-400"><X className="w-4 h-4" /></button>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2 group">
                        <span className="font-mono text-white">{formatPrice(item.price)}</span>
                        <button onClick={() => startEditing(item)} className="opacity-0 group-hover:opacity-100 text-gray-500 hover:text-white"><Edit2 className="w-3 h-3" /></button>
                      </div>
                    )}
                  </div>

                  {/* Controls */}
                  <div className="flex items-center gap-4">
                    <button 
                      onClick={() => handleToggleAvailability(item)}
                      className={`px-4 py-2 text-xs font-bold uppercase tracking-widest min-w-[100px] ${item.isAvailable ? 'bg-white text-black hover:bg-gray-200' : 'bg-red-600 text-white hover:bg-red-500'}`}
                    >
                      {item.isAvailable ? 'In Stock' : 'Sold Out'}
                    </button>

                    <button 
                      onClick={() => handleDeleteItem(item.id)}
                      className="p-2 text-gray-600 hover:text-red-500 transition-colors"
                      title="Delete Item"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* --- ORDERS VIEW --- */}
      {currentView === 'orders' && (
        <div className="space-y-8 animate-fade-in">
          <div className="flex gap-8 border-b border-gray-800">
              <button 
                onClick={() => setActiveOrderTab('active')}
                className={`pb-4 text-sm font-bold uppercase tracking-widest transition-all duration-300 ${activeOrderTab === 'active' ? 'border-b-2 border-white text-white' : 'border-transparent text-gray-500 hover:text-white'}`}
              >
                Live Orders ({activeOrders.length})
              </button>
              <button 
                onClick={() => setActiveOrderTab('completed')}
                className={`pb-4 text-sm font-bold uppercase tracking-widest transition-all duration-300 ${activeOrderTab === 'completed' ? 'border-b-2 border-white text-white' : 'border-transparent text-gray-500 hover:text-white'}`}
              >
                Archive
              </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {displayOrders.length === 0 && (
              <div className="col-span-full text-center py-24 border border-dashed border-gray-800 animate-fade-in">
                <Coffee className="w-8 h-8 text-gray-600 mx-auto mb-4" />
                <p className="text-gray-500 font-mono text-sm">No orders in queue.</p>
              </div>
            )}

            {displayOrders.map(order => (
              <div key={order.id} className={`bg-black border p-6 transition-all duration-500 animate-fade-in relative ${order.status === OrderStatus.READY ? 'border-white ring-1 ring-white' : 'border-gray-800'}`}>
                {order.status === OrderStatus.READY && (
                    <div className="absolute top-0 left-0 right-0 bg-white text-black text-xs font-bold text-center py-1 uppercase tracking-widest animate-pop">Ready for Pickup</div>
                )}

                <div className={`flex justify-between items-start mb-4 ${order.status === OrderStatus.READY ? 'mt-4' : ''}`}>
                  <div>
                    <h3 className="font-bold text-xl text-white">{order.customerName || order.userEmail.split('@')[0]}</h3>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="font-mono text-xs text-gray-500">#{order.id.slice(0, 6)}</span>
                      {order.customerMobile && (
                        <a href={`tel:${order.customerMobile}`} className="flex items-center text-xs text-gray-400 hover:text-white">
                          <Phone className="w-3 h-3 mr-1" /> {order.customerMobile}
                        </a>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-2xl font-mono font-medium text-white">{formatTime(order.scheduledTime)}</p>
                    <p className="text-xs text-gray-400 font-mono mt-1">{formatPrice(order.totalAmount)}</p>
                  </div>
                </div>

                {/* Transaction ID Display */}
                <div className="bg-gray-900 border border-gray-800 p-2 mb-4 flex items-center justify-between">
                  <div>
                    <span className="block text-[10px] text-gray-500 uppercase tracking-wider">Transaction ID</span>
                    <span className="text-xs font-mono text-white">{order.transactionId || 'N/A'}</span>
                  </div>
                  {order.transactionId && (
                    <button 
                      onClick={() => copyToClipboard(order.transactionId)}
                      className="text-gray-400 hover:text-white p-1"
                      title="Copy ID"
                    >
                      {copiedId === order.transactionId ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
                    </button>
                  )}
                </div>

                <div className="border-t border-b border-gray-800 py-4 mb-6 space-y-2">
                  {order.items.map((item, i) => (
                    <div key={i} className="flex justify-between text-sm">
                      <span className="font-medium text-gray-300"><span className="font-mono text-gray-500 mr-2">{item.quantity}x</span> {item.name}</span>
                    </div>
                  ))}
                </div>

                <div className="grid grid-cols-2 gap-3">
                  {order.status === OrderStatus.PENDING && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.CONFIRMED)}
                      className="col-span-2 flex items-center justify-center gap-2 bg-white text-black py-3 text-xs font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors duration-200"
                    >
                      Verify & Accept
                    </button>
                  )}
                  {order.status === OrderStatus.CONFIRMED && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.PREPARING)}
                      className="col-span-2 flex items-center justify-center gap-2 border border-white bg-black text-white py-3 text-xs font-bold uppercase tracking-widest hover:bg-white hover:text-black transition-colors duration-200"
                    >
                      Start Preparation
                    </button>
                  )}
                  {order.status === OrderStatus.PREPARING && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.READY)}
                      className="col-span-2 flex items-center justify-center gap-2 bg-white text-black py-3 text-xs font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors duration-200"
                    >
                      Mark Ready
                    </button>
                  )}
                  {order.status === OrderStatus.READY && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.COMPLETED)}
                      className="col-span-2 flex items-center justify-center gap-2 border border-gray-700 text-gray-400 py-3 text-xs font-bold uppercase tracking-widest hover:border-white hover:text-white transition-colors duration-200"
                    >
                      Archive
                    </button>
                  )}

                  {(order.status === OrderStatus.PENDING || order.status === OrderStatus.CONFIRMED || order.status === OrderStatus.PREPARING) && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.CANCELLED)}
                      className="col-span-2 text-center text-xs text-gray-500 hover:text-red-500 hover:underline mt-1 transition-colors duration-200"
                    >
                      Reject / Cancel
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, Navigate } from '../contexts/AuthContext';
import { ROUTES } from '../constants';
import { AlertTriangle } from 'lucide-react';
import { checkRateLimit, resetRateLimit, validatePassword, validateEmail } from '../utils/security';
import { UserRole } from '../types';

type Tab = 'login' | 'signup';

export const Login: React.FC = () => {
  const { user, signInWithGoogle, loginWithEmail, signupWithEmail, loading, error: authError } = useAuth();
  // We rely on the reactive redirect below, but useNavigate is available if needed.
  const [activeTab, setActiveTab] = useState<Tab>('login');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState('');

  if (loading) return null;

  // Automatic Redirect based on Role
  if (user) {
    return <Navigate to={user.role === UserRole.ADMIN ? ROUTES.ADMIN : ROUTES.HOME} replace />;
  }

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setLocalError('');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLocalError('');

    // --- Validation & Security Checks ---

    // 1. Rate Limiting for Login
    if (activeTab === 'login') {
      const rateLimit = checkRateLimit(email);
      if (!rateLimit.allowed) {
        setLocalError(`Too many attempts. Please try again in ${rateLimit.waitTimeMinutes} minutes.`);
        return;
      }
    }

    // 2. Email Validation
    if (!validateEmail(email)) {
       setLocalError("Please enter a valid email address.");
       return;
    }

    // 3. Password Validation (Strict check for signup)
    if (activeTab === 'signup') {
      const passValidation = validatePassword(password);
      if (!passValidation.isValid) {
        setLocalError(passValidation.message || "Invalid password.");
        return;
      }
      if (!name.trim()) {
        setLocalError("Name is required");
        return;
      }
    }

    setIsSubmitting(true);

    try {
      if (activeTab === 'signup') {
        await signupWithEmail(email, password, name);
      } else {
        await loginWithEmail(email, password);
        // Successful login, reset rate limit
        resetRateLimit(email);
      }
      // We do not manually navigate here. 
      // Successful auth will update the `user` object in context, triggering the redirect above.
    } catch (err: any) {
      // Don't reveal exactly why it failed to prevent enumeration (handled generically in AuthContext for user-not-found/wrong-password)
      setLocalError(err.message || "Action failed");
      setIsSubmitting(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLocalError('');
    try {
      await signInWithGoogle();
      // Redirect handled by reactive `user` check
    } catch (err: any) {
      setLocalError(err.message);
    }
  };

  const displayError = localError || authError;

  return (
    <div className="min-h-[70vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-md w-full bg-black">

        <div className="text-center mb-12">
          <h1 className="text-4xl font-serif font-bold text-white mb-2">
            {activeTab === 'signup' ? 'Join Us' : 'Welcome Back'}
          </h1>
          <p className="text-gray-400 font-light">
            {activeTab === 'signup' ? 'Create your account' : 'Access your account'}
          </p>
        </div>

        <div className="flex border-b border-gray-800 mb-8">
          <button
            onClick={() => handleTabChange('login')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'login' ? 'text-white border-b-2 border-white' : 'text-gray-600 hover:text-gray-400'}`}
          >
            Login
          </button>
          <button
            onClick={() => handleTabChange('signup')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'signup' ? 'text-white border-b-2 border-white' : 'text-gray-600 hover:text-gray-400'}`}
          >
            Register
          </button>
        </div>

        <div>
          {displayError && (
            <div className="mb-8 p-4 border border-white flex items-start text-left bg-gray-900">
              <AlertTriangle className="w-5 h-5 text-white mr-3 flex-shrink-0" />
              <p className="text-sm font-medium text-white">{displayError}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {activeTab === 'signup' && (
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Full Name</label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors"
                  required
                />
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors disabled:bg-gray-900 disabled:text-gray-600"
                required
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Password</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors"
                required
                minLength={6}
              />
              {activeTab === 'signup' && (
                <p className="text-[10px] text-gray-500">Min 8 chars, 1 uppercase, 1 lowercase, 1 number.</p>
              )}
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-white text-black py-4 font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors disabled:opacity-50 mt-4"
            >
              {isSubmitting ? 'Processing...' : activeTab === 'signup' ? 'Create Account' : 'Enter'}
            </button>
          </form>

          <div className="relative my-10 text-center">
            <span className="bg-black px-4 text-xs text-gray-400 uppercase tracking-widest">or</span>
            <div className="absolute top-1/2 left-0 w-full border-t border-gray-800 -z-10"></div>
          </div>

          <button
            type="button"
            onClick={handleGoogleLogin}
            className="w-full flex items-center justify-center gap-3 border border-white py-4 text-sm font-bold uppercase tracking-widest hover:bg-white hover:text-black transition-all text-white"
          >
            <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-5 h-5 bg-white rounded-full" />
            Continue with Google
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { Navigate } from '../contexts/AuthContext';
import { ROUTES } from '../constants';
import { AlertTriangle } from 'lucide-react';
import { checkRateLimit, resetRateLimit, validatePassword, validateEmail } from '../utils/security';
import { UserRole } from '../types';

type Tab = 'login' | 'signup';

export const Login: React.FC = () => {
  const { user, signInWithGoogle, loginWithEmail, signupWithEmail, loading, error: authError } = useAuth();
  // We rely on the reactive redirect below.
  const [activeTab, setActiveTab] = useState<Tab>('login');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState('');

  if (loading) return null;

  // Automatic Redirect based on Role
  if (user) {
    return <Navigate to={user.role === UserRole.ADMIN ? ROUTES.ADMIN : ROUTES.HOME} replace />;
  }

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setLocalError('');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLocalError('');

    // --- Validation & Security Checks ---

    // 1. Rate Limiting for Login
    if (activeTab === 'login') {
      const rateLimit = checkRateLimit(email);
      if (!rateLimit.allowed) {
        setLocalError(`Too many attempts. Please try again in ${rateLimit.waitTimeMinutes} minutes.`);
        return;
      }
    }

    // 2. Email Validation
    if (!validateEmail(email)) {
       setLocalError("Please enter a valid email address.");
       return;
    }

    // 3. Password Validation (Strict check for signup)
    if (activeTab === 'signup') {
      const passValidation = validatePassword(password);
      if (!passValidation.isValid) {
        setLocalError(passValidation.message || "Invalid password.");
        return;
      }
      if (!name.trim()) {
        setLocalError("Name is required");
        return;
      }
    }

    setIsSubmitting(true);

    try {
      if (activeTab === 'signup') {
        await signupWithEmail(email, password, name);
      } else {
        await loginWithEmail(email, password);
        // Successful login, reset rate limit
        resetRateLimit(email);
      }
      // We do not manually navigate here. 
      // Successful auth will update the `user` object in context, triggering the redirect above.
    } catch (err: any) {
      // Don't reveal exactly why it failed to prevent enumeration (handled generically in AuthContext for user-not-found/wrong-password)
      setLocalError(err.message || "Action failed");
      setIsSubmitting(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLocalError('');
    try {
      await signInWithGoogle();
      // Redirect handled by reactive `user` check
    } catch (err: any) {
      setLocalError(err.message);
    }
  };

  const displayError = localError || authError;

  return (
    <div className="min-h-[70vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-md w-full bg-black">

        <div className="text-center mb-12">
          <h1 className="text-4xl font-serif font-bold text-white mb-2">
            {activeTab === 'signup' ? 'Join Us' : 'Welcome Back'}
          </h1>
          <p className="text-gray-400 font-light">
            {activeTab === 'signup' ? 'Create your account' : 'Access your account'}
          </p>
        </div>

        <div className="flex border-b border-gray-800 mb-8">
          <button
            onClick={() => handleTabChange('login')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'login' ? 'text-white border-b-2 border-white' : 'text-gray-600 hover:text-gray-400'}`}
          >
            Login
          </button>
          <button
            onClick={() => handleTabChange('signup')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'signup' ? 'text-white border-b-2 border-white' : 'text-gray-600 hover:text-gray-400'}`}
          >
            Register
          </button>
        </div>

        <div>
          {displayError && (
            <div className="mb-8 p-4 border border-white flex items-start text-left bg-gray-900">
              <AlertTriangle className="w-5 h-5 text-white mr-3 flex-shrink-0" />
              <p className="text-sm font-medium text-white">{displayError}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {activeTab === 'signup' && (
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Full Name</label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors"
                  required
                />
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors disabled:bg-gray-900 disabled:text-gray-600"
                required
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Password</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 bg-black border border-gray-700 focus:border-white text-white outline-none transition-colors"
                required
                minLength={6}
              />
              {activeTab === 'signup' && (
                <p className="text-[10px] text-gray-500">Min 8 chars, 1 uppercase, 1 lowercase, 1 number.</p>
              )}
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-white text-black py-4 font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors disabled:opacity-50 mt-4"
            >
              {isSubmitting ? 'Processing...' : activeTab === 'signup' ? 'Create Account' : 'Enter'}
            </button>
          </form>

          <div className="relative my-10 text-center">
            <span className="bg-black px-4 text-xs text-gray-400 uppercase tracking-widest">or</span>
            <div className="absolute top-1/2 left-0 w-full border-t border-gray-800 -z-10"></div>
          </div>

          <button
            type="button"
            onClick={handleGoogleLogin}
            className="w-full flex items-center justify-center gap-3 border border-white py-4 text-sm font-bold uppercase tracking-widest hover:bg-white hover:text-black transition-all text-white"
          >
            <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-5 h-5 bg-white rounded-full" />
            Continue with Google
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import { UPI_VPA, UPI_PAYEE_NAME, APP_NAME } from '../constants';
import { formatPrice } from '../utils/formatters';
import { Loader2, Send, Smartphone, Copy, Check } from 'lucide-react';

interface UPIPaymentProps {
  amount: number;
  onSuccess: (transactionId: string) => Promise<void>;
  onCancel: () => void;
}

export const UPIPayment: React.FC<UPIPaymentProps> = ({ amount, onSuccess, onCancel }) => {
  const [transactionId, setTransactionId] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [copied, setCopied] = useState(false);

  // Generate a unique transaction reference for this session
  // This helps banking apps identify the transaction and often bypasses generic security blocks
  const transactionRef = useMemo(() => `T${Date.now()}`, []);

  // Construct UPI URL
  // format: upi://pay?pa=<vpa>&pn=<name>&am=<amount>&cu=<currency>&tn=<note>&tr=<ref>
  const upiUrl = `upi://pay?pa=${UPI_VPA}&pn=${encodeURIComponent(UPI_PAYEE_NAME)}&am=${amount.toFixed(2)}&cu=INR&tn=${encodeURIComponent(`Order at ${APP_NAME}`)}&tr=${transactionRef}`;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!transactionId.trim()) {
      setError("Please enter the Transaction ID / UTR");
      return;
    }

    setError('');
    setIsSubmitting(true);
    try {
      await onSuccess(transactionId);
    } catch (err) {
      setError("Failed to process order. Please try again.");
      setIsSubmitting(false);
    }
  };

  const copyVpa = () => {
    navigator.clipboard.writeText(UPI_VPA);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="animate-fade-in space-y-8">

      <div className="bg-white text-black p-6 border border-gray-200">
        <h3 className="font-serif font-bold text-xl mb-6 text-center">Scan or Click to Pay</h3>

        <div className="flex flex-col items-center justify-center space-y-6">
          <div className="bg-white p-4 border-2 border-dashed border-gray-300 relative">
             <QRCodeSVG value={upiUrl} size={200} />
          </div>

          <div className="w-full space-y-3 md:hidden">
            <a 
              href={upiUrl}
              className="flex items-center justify-center w-full px-6 py-4 bg-black text-white font-bold uppercase tracking-widest text-sm hover:bg-gray-800 transition-colors rounded-none"
            >
              <Smartphone className="w-4 h-4 mr-2" /> Pay via UPI App
            </a>
            <p className="text-[10px] text-center text-gray-500">
              If the button doesn't work, copy the UPI ID below and pay manually.
            </p>
          </div>

          <div className="text-center w-full">
            <p className="text-3xl font-mono font-bold">{formatPrice(amount)}</p>
            <div className="flex items-center justify-center gap-2 mt-2">
              <span className="text-xs text-gray-500 uppercase tracking-widest">To: {UPI_PAYEE_NAME}</span>
            </div>

            <button 
              onClick={copyVpa}
              className="mt-2 flex items-center justify-center gap-2 text-xs font-mono bg-gray-100 px-3 py-1 rounded mx-auto hover:bg-gray-200 transition-colors"
            >
              {UPI_VPA}
              {copied ? <Check className="w-3 h-3 text-green-600" /> : <Copy className="w-3 h-3 text-gray-500" />}
            </button>
          </div>
        </div>

        <div className="mt-6 pt-6 border-t border-gray-200">
          <p className="text-xs text-center text-gray-500 leading-relaxed">
             1. Open PhonePe, Google Pay, or Paytm.<br/>
             2. Scan QR code OR Click 'Pay via UPI App'.<br/>
             3. Complete payment and <strong>copy the UTR / Transaction ID.</strong><br/>
             4. Paste the ID below to confirm.
          </p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="bg-black border border-white p-6">
        <h4 className="text-white font-serif font-bold mb-4">Verification</h4>

        <div className="space-y-4">
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Transaction ID / UTR</label>
            <input 
              type="text" 
              value={transactionId}
              onChange={(e) => setTransactionId(e.target.value)}
              placeholder="e.g. 308572189..."
              className="w-full bg-gray-900 border border-gray-700 px-4 py-3 focus:border-white text-white outline-none transition-colors font-mono"
            />
            {error && <p className="text-red-500 text-xs mt-2">{error}</p>}
          </div>

          <div className="flex gap-4 pt-2">
            <button
              type="button"
              onClick={onCancel}
              disabled={isSubmitting}
              className="flex-1 py-4 text-sm font-bold uppercase tracking-widest text-gray-500 hover:text-white transition-colors border border-transparent hover:border-gray-800"
            >
              Back
            </button>
            <button
              type="submit"
              disabled={!transactionId || isSubmitting}
              className="flex-1 bg-white text-black py-4 text-sm font-bold uppercase tracking-widest hover:bg-gray-200 transition-colors disabled:opacity-50 flex justify-center items-center"
            >
              {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <>Submit Order <Send className="w-4 h-4 ml-2" /></>}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useStore } from '../contexts/StoreContext';
import { 
  subscribeToAllOrders, 
  updateOrderStatus, 
  getAllMenuItemsAdmin,
  updateMenuItem,
  addMenuItem,
  deleteMenuItem
} from '../services/firestoreService';
import { Order, OrderStatus, MenuItem, ProductCategory } from '../types';
import { formatTime, formatPrice } from '../utils/formatters';
import { Navigate } from '../contexts/AuthContext';
import { ROUTES } from '../constants';
import { Coffee, Copy, Check, Phone, Power, Loader2, Package, Plus, Trash2, Save, X, Edit2, Wand2, Flame } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

export const AdminDashboard: React.FC = () => {
  const { user, isAdmin } = useAuth();
  const { isStoreOpen, setStoreOpen } = useStore();

  // View State
  const [currentView, setCurrentView] = useState<'orders' | 'inventory'>('orders');

  // Orders State
  const [orders, setOrders] = useState<Order[]>([]);
  const [activeOrderTab, setActiveOrderTab] = useState<'active' | 'completed'>('active');
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // Store Toggle State
  const [isTogglingStore, setIsTogglingStore] = useState(false);

  // Inventory State
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [isInventoryLoading, setIsInventoryLoading] = useState(false);
  const [editingItemId, setEditingItemId] = useState<string | null>(null);
  const [editPrice, setEditPrice] = useState<string>('');

  // Add Item Form State
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [newItem, setNewItem] = useState({
    name: '',
    description: '',
    price: '',
    category: ProductCategory.Snacks,
    imageUrl: '',
    preparationTime: '10',
    calories: '',
    isAvailable: true
  });

  useEffect(() => {
    if (!isAdmin) return;
    const unsubscribe = subscribeToAllOrders((data) => {
      setOrders(data);
    });
    return () => unsubscribe();
  }, [isAdmin]);

  // Load inventory when switching to inventory view
  useEffect(() => {
    if (currentView === 'inventory' && isAdmin) {
      loadInventory();
    }
  }, [currentView, isAdmin]);

  const loadInventory = async () => {
    setIsInventoryLoading(true);
    try {
      const items = await getAllMenuItemsAdmin();
      setMenuItems(items);
    } catch (e) {
      console.error("Failed to load inventory", e);
    } finally {
      setIsInventoryLoading(false);
    }
  };

  if (!user || !isAdmin) return <Navigate to={ROUTES.HOME} replace />;

  // --- ORDER HANDLERS ---
  const handleStatusUpdate = async (orderId: string, newStatus: OrderStatus) => {
    try {
      await updateOrderStatus(orderId, newStatus);
    } catch (e) {
      console.error("Failed to update status", e);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(text);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleToggleStore = async () => {
    setIsTogglingStore(true);
    try {
      await setStoreOpen(!isStoreOpen);
    } catch (error: any) {
      console.error("Failed to toggle store", error);
      alert(`Error updating store status: ${error.message || 'Unknown error'}. Check your internet or permissions.`);
    } finally {
      setIsTogglingStore(false);
    }
  };

  // --- INVENTORY HANDLERS ---
  const handleToggleAvailability = async (item: MenuItem) => {
    try {
      // Optimistic update
      setMenuItems(prev => prev.map(i => i.id === item.id ? { ...i, isAvailable: !i.isAvailable } : i));
      await updateMenuItem(item.id, { isAvailable: !item.isAvailable });
    } catch (e) {
      console.error("Failed to update item availability", e);
      // Revert on failure
      loadInventory();
      alert("Failed to update item.");
    }
  };

  const startEditing = (item: MenuItem) => {
    setEditingItemId(item.id);
    setEditPrice(item.price.toString());
  };

  const savePriceEdit = async (id: string) => {
    const newPrice = parseFloat(editPrice);
    if (isNaN(newPrice) || newPrice <= 0) {
      alert("Please enter a valid price");
      return;
    }
    try {
      await updateMenuItem(id, { price: newPrice });
      setMenuItems(prev => prev.map(i => i.id === id ? { ...i, price: newPrice } : i));
      setEditingItemId(null);
    } catch (e) {
      alert("Failed to update price");
    }
  };

  const handleDeleteItem = async (id: string) => {
    if (!window.confirm("Are you sure you want to delete this item? This cannot be undone.")) return;
    try {
      await deleteMenuItem(id);
      setMenuItems(prev => prev.filter(i => i.id !== id));
    } catch (e) {
      alert("Failed to delete item");
    }
  };

  const generateDetails = async () => {
    if (!newItem.name.trim()) return;
    setIsGenerating(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-latest',
            contents: `Generate a short, enticing menu description (max 15 words) and estimate calories for a dish named "${newItem.name}".`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        description: { type: Type.STRING },
                        calories: { type: Type.INTEGER }
                    }
                }
            }
        });

        const text = response.text;
        if (text) {
            const data = JSON.parse(text);
            setNewItem(prev => ({
                ...prev,
                description: prev.description || data.description || '',
                calories: prev.calories || (data.calories ? data.calories.toString() : '')
            }));
        }
    } catch (e) {
        console.error("AI Generation failed", e);
        // Fallback or silent fail
    } finally {
        setIsGenerating(false);
    }
  };

  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addMenuItem({
        name: newItem.name,
        description: newItem.description,
        price: parseFloat(newItem.price),
        category: newItem.category,
        imageUrl: newItem.imageUrl || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c',
        preparationTime: parseInt(newItem.preparationTime),
        isAvailable: newItem.isAvailable,
        calories: newItem.calories ? parseInt(newItem.calories) : undefined
      });
      setIsAddingItem(false);
      setNewItem({
        name: '', description: '', price: '', category: ProductCategory.Snacks, 
        imageUrl: '', preparationTime: '10', calories: '', isAvailable: true
      });
      loadInventory();
    } catch (error: any) {
      alert("Failed to add item: " + error.message);
    }
  };

  const activeOrders = orders.filter(o => [OrderStatus.PENDING, OrderStatus.CONFIRMED, OrderStatus.PREPARING, OrderStatus.READY].includes(o.status));
  const completedOrders = orders.filter(o => [OrderStatus.COMPLETED, OrderStatus.CANCELLED].includes(o.status));
  const displayOrders = activeOrderTab === 'active' ? activeOrders : completedOrders;

  return (
    <div className="space-y-8 pb-20">
      {/* HEADER AREA */}
      <div className="flex flex-col xl:flex-row xl:items-end justify-between gap-6 border-b border-white pb-8">
        <div>
           <h1 className="text-4xl font-serif font-bold text-white animate-fade-in">Command Center</h1>
           <p className="text-gray-400 mt-2 text-sm">Manage orders, inventory, and store status.</p>
        </div>

        <div className="flex flex-wrap gap-4">
          <button
            onClick={() => setCurrentView('orders')}
            className={`px-6 py-3 text-sm font-bold uppercase tracking-widest transition-all ${currentView === 'orders' ? 'bg-white text-black' : 'bg-gray-900 text-gray-400 hover:text-white'}`}
          >
            Orders
          </button>

          <button
            onClick={() => setCurrentView('inventory')}
            className={`flex items-center gap-2 px-6 py-3 text-sm font-bold uppercase tracking-widest transition-all ${currentView === 'inventory' ? 'bg-white text-black' : 'bg-gray-900 text-gray-400 hover:text-white'}`}
          >
            <Package className="w-4 h-4" /> Inventory
          </button>

          {/* Store Controls */}
          <button 
            onClick={handleToggleStore}
            disabled={isTogglingStore}
            className={`flex items-center gap-3 px-6 py-3 text-sm font-bold uppercase tracking-widest border transition-all duration-300 ${
              isStoreOpen 
                ? 'bg-green-500 text-black border-green-500 hover:bg-green-400' 
                : 'bg-red-900 text-white border-red-900 hover:bg-red-800'
            }`}
          >
            {isTogglingStore ? <Loader2 className="w-4 h-4 animate-spin" /> : <Power className="w-4 h-4" />}
            {isStoreOpen ? 'Online' : 'Offline'}
          </button>
        </div>
      </div>

      {/* --- INVENTORY VIEW --- */}
      {currentView === 'inventory' && (
        <div className="animate-fade-in space-y-8">

          {/* Add Item Button */}
          {!isAddingItem ? (
            <button 
              onClick={() => setIsAddingItem(true)}
              className="w-full border border-dashed border-gray-700 p-8 text-gray-500 hover:text-white hover:border-white transition-colors flex flex-col items-center justify-center gap-2"
            >
              <Plus className="w-8 h-8" />
              <span className="text-sm font-bold uppercase tracking-widest">Add New Menu Item</span>
            </button>
          ) : (
             <form onSubmit={handleAddItem} className="bg-gray-900 border border-gray-800 p-6 space-y-4">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-white font-bold uppercase tracking-widest">Add New Item</h3>
                  <button type="button" onClick={() => setIsAddingItem(false)}><X className="text-gray-400 hover:text-white" /></button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   <div className="md:col-span-2 relative">
                     <input 
                        required 
                        placeholder="Item Name" 
                        value={newItem.name} 
                        onChange={e => setNewItem({...newItem, name: e.target.value})} 
                        className="w-full bg-black border border-gray-700 p-3 pr-12 text-white outline-none focus:border-white" 
                     />
                     <button
                        type="button"
                        onClick={generateDetails}
                        disabled={isGenerating || !newItem.name.trim()}
                        className="absolute right-2 top-2 p-1.5 text-gray-400 hover:text-white disabled:opacity-30 transition-colors"
                        title="Auto-fill details with AI"
                     >
                        {isGenerating ? <Loader2 className="w-5 h-5 animate-spin" /> : <Wand2 className="w-5 h-5" />}
                     </button>
                   </div>

                   <input required type="number" step="0.01" placeholder="Price" value={newItem.price} onChange={e => setNewItem({...newItem, price: e.target.value})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white" />

                   <select value={newItem.category} onChange={e => setNewItem({...newItem, category: e.target.value as ProductCategory})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white">
                      {Object.values(ProductCategory).map(c => <option key={c} value={c}>{c}</option>)}
                   </select>

                   <input type="number" placeholder="Prep Time (mins)" value={newItem.preparationTime} onChange={e => setNewItem({...newItem, preparationTime: e.target.value})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white" />

                   <input type="number" placeholder="Calories (e.g. 350)" value={newItem.calories} onChange={e => setNewItem({...newItem, calories: e.target.value})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white" />

                   <input placeholder="Image URL" value={newItem.imageUrl} onChange={e => setNewItem({...newItem, imageUrl: e.target.value})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white md:col-span-2" />

                   <textarea placeholder="Description" value={newItem.description} onChange={e => setNewItem({...newItem, description: e.target.value})} className="bg-black border border-gray-700 p-3 text-white outline-none focus:border-white md:col-span-2 h-24" />
                </div>
                <button type="submit" className="w-full bg-white text-black py-3 font-bold uppercase tracking-widest hover:bg-gray-200">Save Item</button>
             </form>
          )}

