      setMenuItems(items);
    } catch (e) {
      console.error("Failed to load inventory", e);
    } finally {
      setIsInventoryLoading(false);
    }
  };

  if (!user || !isAdmin) return <Navigate to={ROUTES.HOME} replace />;

  // --- ORDER HANDLERS ---
  const handleStatusUpdate = async (orderId: string, newStatus: OrderStatus) => {
    try {
      await updateOrderStatus(orderId, newStatus);
    } catch (e) {
      console.error("Failed to update status", e);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(text);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleToggleStore = async () => {
    setIsTogglingStore(true);
    try {
      await setStoreOpen(!isStoreOpen);
    } catch (error: any) {
      console.error("Failed to toggle store", error);
      alert(`Error updating store status: ${error.message || 'Unknown error'}. Check your internet or permissions.`);
    } finally {
      setIsTogglingStore(false);
    }
  };

  // --- INVENTORY HANDLERS ---
  const handleToggleAvailability = async (item: MenuItem) => {
    try {
      // Optimistic update
      setMenuItems(prev => prev.map(i => i.id === item.id ? { ...i, isAvailable: !i.isAvailable } : i));
      await updateMenuItem(item.id, { isAvailable: !item.isAvailable });
    } catch (e) {
      console.error("Failed to update item availability", e);
      // Revert on failure
      loadInventory();
      alert("Failed to update item.");
    }
  };

  const startEditing = (item: MenuItem) => {
    setEditingItemId(item.id);
    setEditPrice(item.price.toString());
  };

  const savePriceEdit = async (id: string) => {
    const newPrice = parseFloat(editPrice);
    if (isNaN(newPrice) || newPrice <= 0) {
      alert("Please enter a valid price");
      return;
    }
    try {
      await updateMenuItem(id, { price: newPrice });
      setMenuItems(prev => prev.map(i => i.id === id ? { ...i, price: newPrice } : i));
      setEditingItemId(null);
    } catch (e) {
      alert("Failed to update price");
    }
  };

  const handleDeleteItem = async (id: string) => {
    if (!window.confirm("Are you sure you want to delete this item? This cannot be undone.")) return;
    try {
      await deleteMenuItem(id);
      setMenuItems(prev => prev.filter(i => i.id !== id));
    } catch (e) {
      alert("Failed to delete item");
    }
  };

  const generateDetails = async () => {
    if (!newItem.name.trim()) return;

    setIsGenerating(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `For a dish named "${newItem.name}", generate:
            1. A short menu description (max 15 words).
            2. Estimated calories (integer only).
            3. Fitness goal category: return "muscle_gain" if it is high protein/nutrient dense, or "weight_loss" if it is low calorie/light.`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        description: { type: Type.STRING },
                        calories: { type: Type.INTEGER },
                        fitnessGoal: { type: Type.STRING, enum: ["muscle_gain", "weight_loss"] }
                    }
                }
            }
        });

        const text = response.text;
        if (text) {
            const data = JSON.parse(text);
            setNewItem(prev => ({
                ...prev,
                description: data.description || prev.description,
                calories: data.calories ? data.calories.toString() : prev.calories,
                fitnessGoal: (data.fitnessGoal as 'muscle_gain' | 'weight_loss') || prev.fitnessGoal
            }));
        }
    } catch (e) {
        console.error("AI Generation failed", e);
    } finally {
        setIsGenerating(false);
    }
  };

  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addMenuItem({
        name: newItem.name,
        description: newItem.description,
        price: parseFloat(newItem.price),
        category: newItem.category,
        imageUrl: newItem.imageUrl || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c',
        preparationTime: parseInt(newItem.preparationTime),
        isAvailable: newItem.isAvailable,
        calories: newItem.calories ? parseInt(newItem.calories) : undefined,
        fitnessGoal: newItem.fitnessGoal || undefined
      });
      setIsAddingItem(false);
      setNewItem({
        name: '', description: '', price: '', category: ProductCategory.Snacks, 
        imageUrl: '', preparationTime: '10', calories: '', isAvailable: true, fitnessGoal: ''
      });
      loadInventory();
    } catch (error: any) {
      alert("Failed to add item: " + error.message);
    }
  };

  const activeOrders = orders.filter(o => [OrderStatus.PENDING, OrderStatus.CONFIRMED, OrderStatus.PREPARING, OrderStatus.READY].includes(o.status));
  const completedOrders = orders.filter(o => [OrderStatus.COMPLETED, OrderStatus.CANCELLED].includes(o.status));
  const displayOrders = activeOrderTab === 'active' ? activeOrders : completedOrders;

  return (
    <div className="space-y-8 pb-20">
      {user && <WelcomeToast name={user.displayName} />}

      {/* HEADER AREA */}
      <div className="flex flex-col xl:flex-row xl:items-end justify-between gap-6 border-b border-black dark:border-white pb-8 transition-colors duration-300">
        <div>
           <h1 className="text-4xl font-serif font-bold text-black dark:text-white animate-fade-in">Command Center</h1>
           <p className="text-gray-600 dark:text-gray-400 mt-2 text-sm">Manage orders, inventory, and store status.</p>
        </div>

        <div className="flex flex-wrap gap-4">
          <button
            onClick={() => setCurrentView('orders')}
            className={`px-6 py-3 text-sm font-bold uppercase tracking-widest transition-all ${currentView === 'orders' ? 'bg-black dark:bg-white text-white dark:text-black' : 'bg-gray-100 dark:bg-gray-900 text-gray-500 hover:text-black dark:hover:text-white'}`}
          >
            Orders
          </button>

          <button
            onClick={() => setCurrentView('inventory')}
            className={`flex items-center gap-2 px-6 py-3 text-sm font-bold uppercase tracking-widest transition-all ${currentView === 'inventory' ? 'bg-black dark:bg-white text-white dark:text-black' : 'bg-gray-100 dark:bg-gray-900 text-gray-500 hover:text-black dark:hover:text-white'}`}
          >
            <Package className="w-4 h-4" /> Inventory
          </button>

          {/* Store Controls */}
          <button 
            onClick={handleToggleStore}
            disabled={isTogglingStore}
            className={`flex items-center gap-3 px-6 py-3 text-sm font-bold uppercase tracking-widest border transition-all duration-300 ${
              isStoreOpen 
                ? 'bg-green-500 text-white dark:text-black border-green-500 hover:bg-green-600 dark:hover:bg-green-400' 
                : 'bg-red-700 text-white border-red-700 hover:bg-red-800'
            }`}
          >
            {isTogglingStore ? <Loader2 className="w-4 h-4 animate-spin" /> : <Power className="w-4 h-4" />}
            {isStoreOpen ? 'Online' : 'Offline'}
          </button>
        </div>
      </div>

      {/* --- INVENTORY VIEW --- */}
      {currentView === 'inventory' && (
        <div className="animate-fade-in space-y-8">

          {/* Add Item Button */}
          {!isAddingItem ? (
            <button 
              onClick={() => setIsAddingItem(true)}
              className="w-full border border-dashed border-gray-300 dark:border-gray-700 p-8 text-gray-500 hover:text-black dark:hover:text-white hover:border-black dark:hover:border-white transition-colors flex flex-col items-center justify-center gap-2"
            >
              <Plus className="w-8 h-8" />
              <span className="text-sm font-bold uppercase tracking-widest">Add New Menu Item</span>
            </button>
          ) : (
             <form onSubmit={handleAddItem} className="bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-800 p-8 space-y-6 shadow-sm">
                <div className="flex justify-between items-center mb-2">
                  <h3 className="text-black dark:text-white font-bold uppercase tracking-widest text-lg">Add New Item</h3>
                  <button type="button" onClick={() => setIsAddingItem(false)}><X className="text-gray-400 hover:text-black dark:hover:text-white" /></button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="md:col-span-2 relative group">
                     <label className="text-[10px] text-gray-500 uppercase tracking-widest mb-2 block font-bold">Item Name</label>
                     <input 
                        required 
                        placeholder="e.g. Chicken Caesar Salad" 
                        value={newItem.name} 
                        onChange={e => setNewItem({...newItem, name: e.target.value})}
                        onBlur={generateDetails}
                        className="w-full bg-white dark:bg-black border border-gray-300 dark:border-gray-700 p-4 pr-12 text-black dark:text-white outline-none focus:border-black dark:focus:border-white transition-colors" 
                     />
                     <div className="absolute right-3 top-10 text-gray-400">
                        {isGenerating ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5 opacity-50 group-hover:opacity-100 transition-opacity" />}
                     </div>
                   </div>

                   <div>
                     <label className="text-[10px] text-gray-500 uppercase tracking-widest mb-2 block font-bold">Price</label>
                     <input required type="number" step="0.01" placeholder="0.00" value={newItem.price} onChange={e => setNewItem({...newItem, price: e.target.value})} className="w-full bg-white dark:bg-black border border-gray-300 dark:border-gray-700 p-4 text-black dark:text-white outline-none focus:border-black dark:focus:border-white transition-colors" />
                   </div>

                   <div>
                      <label className="text-[10px] text-gray-500 uppercase tracking-widest mb-2 block font-bold">Category</label>
                      <select value={newItem.category} onChange={e => setNewItem({...newItem, category: e.target.value as ProductCategory})} className="w-full bg-white dark:bg-black border border-gray-300 dark:border-gray-700 p-4 text-black dark:text-white outline-none focus:border-black dark:focus:border-white transition-colors appearance-none">
                          {Object.values(ProductCategory).map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                   </div>

                   <div>
                      <label className="text-[10px] text-gray-500 uppercase tracking-widest mb-2 block font-bold">Prep Time (min)</label>
                      <input type="number" placeholder="10" value={newItem.preparationTime} onChange={e => setNewItem({...newItem, preparationTime: e.target.value})} className="w-full bg-white dark:bg-black border border-gray-300 dark:border-gray-700 p-4 text-black dark:text-white outline-none focus:border-black dark:focus:border-white transition-colors" />
                   </div>

                   <div className="grid grid-cols-2 gap-4 md:col-span-1">
                     <div className="relative">
                       <label className="text-[10px] text-gray-500 uppercase tracking-widest mb-2 block font-bold flex items-center gap-1">
                          Calories {isGenerating && <Loader2 className="w-3 h-3 animate-spin" />}
                       </label>
                       <input 
                          type="number" 
                          placeholder="Auto-calc" 
                          value={newItem.calories} 
                          onChange={e => setNewItem({...newItem, calories: e.target.value})} 
                          className={`w-full bg-white dark:bg-black border border-gray-300 dark:border-gray-700 p-4 text-black dark:text-white outline-none focus:border-black dark:focus:border-white transition-colors ${isGenerating ? 'opacity-50' : ''}`}
                       />
                     </div>

                     <div className="relative">
                       <label className="text-[10px] text-gray-500 uppercase tracking-widest mb-2 block font-bold flex items-center gap-1">
                          Goal {isGenerating && <Loader2 className="w-3 h-3 animate-spin" />}
                       </label>
                       <select 
                          value={newItem.fitnessGoal} 
                          onChange={e => setNewItem({...newItem, fitnessGoal: e.target.value as any})} 
                          className={`w-full bg-white dark:bg-black border border-gray-300 dark:border-gray-700 p-4 text-black dark:text-white outline-none focus:border-black dark:focus:border-white transition-colors appearance-none ${isGenerating ? 'opacity-50' : ''}`}
                       >
                          <option value="">None</option>
                          <option value="muscle_gain">Muscle Gain</option>
                          <option value="weight_loss">Weight Loss</option>
                       </select>
                     </div>
                   </div>

                   <div className="md:col-span-2">
                      <label className="text-[10px] text-gray-500 uppercase tracking-widest mb-2 block font-bold">Image URL</label>
                      <input placeholder="https://..." value={newItem.imageUrl} onChange={e => setNewItem({...newItem, imageUrl: e.target.value})} className="w-full bg-white dark:bg-black border border-gray-300 dark:border-gray-700 p-4 text-black dark:text-white outline-none focus:border-black dark:focus:border-white transition-colors" />
                   </div>

                   <div className="md:col-span-2">
                      <label className="text-[10px] text-gray-500 uppercase tracking-widest mb-2 block font-bold flex items-center gap-1">
                         Description {isGenerating && <Loader2 className="w-3 h-3 animate-spin" />}
                      </label>
                      <textarea 
                        placeholder="Auto-generated description..." 
                        value={newItem.description} 
                        onChange={e => setNewItem({...newItem, description: e.target.value})} 
                        className={`w-full bg-white dark:bg-black border border-gray-300 dark:border-gray-700 p-4 text-black dark:text-white outline-none focus:border-black dark:focus:border-white h-24 transition-colors ${isGenerating ? 'opacity-50' : ''}`} 
                      />
                   </div>
                </div>
                <button type="submit" className="w-full bg-black dark:bg-white text-white dark:text-black py-4 font-bold uppercase tracking-widest hover:bg-gray-800 dark:hover:bg-gray-200 transition-colors">Save Item</button>
             </form>
          )}

          {/* Inventory List */}
          {isInventoryLoading ? (
            <div className="text-center py-12"><Loader2 className="animate-spin w-8 h-8 text-black dark:text-white mx-auto" /></div>
          ) : (
            <div className="grid grid-cols-1 gap-4">
              {menuItems.map(item => (
                <div key={item.id} className={`flex flex-col md:flex-row items-center gap-6 p-6 bg-white dark:bg-black border transition-colors duration-300 ${item.isAvailable ? 'border-gray-200 dark:border-gray-800' : 'border-red-200 dark:border-red-900/50 bg-red-50 dark:bg-red-900/10'}`}>
                  <div className="w-20 h-20 bg-gray-100 dark:bg-gray-900 flex-shrink-0 relative group border border-gray-200 dark:border-gray-800">
                    <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
                    {item.calories && (
                       <div className="absolute bottom-0 left-0 right-0 bg-black/80 text-[10px] text-white text-center py-0.5">
                         {item.calories} cal
                       </div>
                    )}
                  </div>

                  <div className="flex-grow text-center md:text-left">
                    <h3 className="text-xl font-serif font-bold text-black dark:text-white">{item.name}</h3>
                    <div className="flex flex-wrap items-center justify-center md:justify-start gap-3 mt-2">
                       <span className="text-xs text-gray-500 uppercase tracking-wider px-2 py-1 bg-gray-100 dark:bg-gray-900">{item.category}</span>
                       {item.calories && (
                         <span className="flex items-center text-xs text-orange-600 dark:text-orange-500">
                           <Flame className="w-3 h-3 mr-0.5" /> {item.calories}
                         </span>
                       )}
                       {item.fitnessGoal === 'muscle_gain' && (
                         <span className="flex items-center text-xs text-blue-600 dark:text-blue-400 font-bold uppercase">
                           <Dumbbell className="w-3 h-3 mr-1" /> Muscle Gain
                         </span>
                       )}
                       {item.fitnessGoal === 'weight_loss' && (
                         <span className="flex items-center text-xs text-green-600 dark:text-green-400 font-bold uppercase">
                           <Scale className="w-3 h-3 mr-1" /> Weight Loss
                         </span>
                       )}
                    </div>
                  </div>

                  {/* Price Editor */}
                  <div className="flex items-center gap-2">
                    {editingItemId === item.id ? (
                      <div className="flex items-center">
                        <input 
                          type="number" 
                          value={editPrice} 
                          onChange={(e) => setEditPrice(e.target.value)}
                          className="w-20 bg-gray-50 dark:bg-gray-900 border border-black dark:border-white p-2 text-black dark:text-white text-sm outline-none"
                          autoFocus
                        />
                        <button onClick={() => savePriceEdit(item.id)} className="p-2 text-green-600 hover:text-green-500"><Save className="w-4 h-4" /></button>
                        <button onClick={() => setEditingItemId(null)} className="p-2 text-red-600 hover:text-red-500"><X className="w-4 h-4" /></button>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2 group">
                        <span className="font-mono text-black dark:text-white font-medium">{formatPrice(item.price)}</span>
                        <button onClick={() => startEditing(item)} className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-black dark:hover:text-white transition-opacity"><Edit2 className="w-3 h-3" /></button>
                      </div>
                    )}
                  </div>

                  {/* Controls */}
                  <div className="flex items-center gap-4">
                    <button 
                      onClick={() => handleToggleAvailability(item)}
                      className={`px-4 py-2 text-xs font-bold uppercase tracking-widest min-w-[100px] transition-colors ${item.isAvailable ? 'bg-black dark:bg-white text-white dark:text-black hover:bg-gray-800 dark:hover:bg-gray-200' : 'bg-red-600 text-white hover:bg-red-500'}`}
                    >
                      {item.isAvailable ? 'In Stock' : 'Sold Out'}
                    </button>

                    <button 
                      onClick={() => handleDeleteItem(item.id)}
                      className="p-2 text-gray-400 hover:text-red-600 transition-colors"
                      title="Delete Item"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* --- ORDERS VIEW --- */}
      {currentView === 'orders' && (
        <div className="space-y-8 animate-fade-in">
          <div className="flex gap-8 border-b border-gray-200 dark:border-gray-800">
              <button 
                onClick={() => setActiveOrderTab('active')}
                className={`pb-4 text-sm font-bold uppercase tracking-widest transition-all duration-300 ${activeOrderTab === 'active' ? 'border-b-2 border-black dark:border-white text-black dark:text-white' : 'border-transparent text-gray-500 hover:text-black dark:hover:text-white'}`}
              >
                Live Orders ({activeOrders.length})
              </button>
              <button 
                onClick={() => setActiveOrderTab('completed')}
                className={`pb-4 text-sm font-bold uppercase tracking-widest transition-all duration-300 ${activeOrderTab === 'completed' ? 'border-b-2 border-black dark:border-white text-black dark:text-white' : 'border-transparent text-gray-500 hover:text-black dark:hover:text-white'}`}
              >
                Archive
              </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {displayOrders.length === 0 && (
              <div className="col-span-full text-center py-24 border border-dashed border-gray-300 dark:border-gray-800 animate-fade-in">
                <Coffee className="w-8 h-8 text-gray-400 dark:text-gray-600 mx-auto mb-4" />
                <p className="text-gray-500 font-mono text-sm">No orders in queue.</p>
              </div>
            )}

            {displayOrders.map(order => (
              <div key={order.id} className={`bg-white dark:bg-black border p-6 transition-all duration-500 animate-fade-in relative ${order.status === OrderStatus.READY ? 'border-black dark:border-white ring-1 ring-black dark:ring-white shadow-xl' : 'border-gray-200 dark:border-gray-800'}`}>
                {order.status === OrderStatus.READY && (
                    <div className="absolute top-0 left-0 right-0 bg-black dark:bg-white text-white dark:text-black text-xs font-bold text-center py-1 uppercase tracking-widest animate-pop">Ready for Pickup</div>
                )}

                <div className={`flex justify-between items-start mb-4 ${order.status === OrderStatus.READY ? 'mt-4' : ''}`}>
                  <div>
                    <h3 className="font-bold text-xl text-black dark:text-white">{order.customerName || order.userEmail.split('@')[0]}</h3>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="font-mono text-xs text-gray-500">#{order.id.slice(0, 6)}</span>
                      {order.customerMobile && (
                        <a href={`tel:${order.customerMobile}`} className="flex items-center text-xs text-gray-400 hover:text-black dark:hover:text-white">
                          <Phone className="w-3 h-3 mr-1" /> {order.customerMobile}
                        </a>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-2xl font-mono font-medium text-black dark:text-white">{formatTime(order.scheduledTime)}</p>
                    <p className="text-xs text-gray-400 font-mono mt-1">{formatPrice(order.totalAmount)}</p>
                  </div>
                </div>

                {/* Transaction ID Display */}
                <div className="bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-800 p-2 mb-4 flex items-center justify-between">
                  <div>
                    <span className="block text-[10px] text-gray-500 uppercase tracking-wider">Transaction ID</span>
                    <span className="text-xs font-mono text-black dark:text-white">{order.transactionId || 'N/A'}</span>
                  </div>
                  {order.transactionId && (
                    <button 
                      onClick={() => copyToClipboard(order.transactionId)}
                      className="text-gray-400 hover:text-black dark:hover:text-white p-1"
                      title="Copy ID"
                    >
                      {copiedId === order.transactionId ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
                    </button>
                  )}
                </div>

                <div className="border-t border-b border-gray-100 dark:border-gray-800 py-4 mb-6 space-y-2">
                  {order.items.map((item, i) => (
                    <div key={i} className="flex justify-between text-sm">
                      <span className="font-medium text-gray-600 dark:text-gray-300"><span className="font-mono text-gray-400 dark:text-gray-500 mr-2">{item.quantity}x</span> {item.name}</span>
                    </div>
                  ))}
                </div>

                <div className="grid grid-cols-2 gap-3">
                  {order.status === OrderStatus.PENDING && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.CONFIRMED)}
                      className="col-span-2 flex items-center justify-center gap-2 bg-black dark:bg-white text-white dark:text-black py-3 text-xs font-bold uppercase tracking-widest hover:bg-gray-800 dark:hover:bg-gray-200 transition-colors duration-200"
                    >
                      Verify & Accept
                    </button>
                  )}
                  {order.status === OrderStatus.CONFIRMED && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.PREPARING)}
                      className="col-span-2 flex items-center justify-center gap-2 border border-black dark:border-white bg-white dark:bg-black text-black dark:text-white py-3 text-xs font-bold uppercase tracking-widest hover:bg-black hover:text-white dark:hover:bg-white dark:hover:text-black transition-colors duration-200"
                    >
                      Start Preparation
                    </button>
                  )}
                  {order.status === OrderStatus.PREPARING && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.READY)}
                      className="col-span-2 flex items-center justify-center gap-2 bg-black dark:bg-white text-white dark:text-black py-3 text-xs font-bold uppercase tracking-widest hover:bg-gray-800 dark:hover:bg-gray-200 transition-colors duration-200"
                    >
                      Mark Ready
                    </button>
                  )}
                  {order.status === OrderStatus.READY && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.COMPLETED)}
                      className="col-span-2 flex items-center justify-center gap-2 border border-gray-300 dark:border-gray-700 text-gray-500 dark:text-gray-400 py-3 text-xs font-bold uppercase tracking-widest hover:border-black dark:hover:border-white hover:text-black dark:hover:text-white transition-colors duration-200"
                    >
                      Archive
                    </button>
                  )}

                  {(order.status === OrderStatus.PENDING || order.status === OrderStatus.CONFIRMED || order.status === OrderStatus.PREPARING) && (
                    <button 
                      onClick={() => handleStatusUpdate(order.id, OrderStatus.CANCELLED)}
                      className="col-span-2 text-center text-xs text-gray-500 hover:text-red-600 dark:hover:text-red-500 hover:underline mt-1 transition-colors duration-200"
                    >
                      Reject / Cancel
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Link, useLocation } from '../contexts/AuthContext';
import { useAuth } from '../contexts/AuthContext';
import { useCart } from '../contexts/CartContext';
import { useStore } from '../contexts/StoreContext';
import { useTheme } from '../contexts/ThemeContext';
import { ShoppingBag, User, LogOut, Menu as MenuIcon, X, Lock, Sun, Moon } from 'lucide-react';
import { CartDrawer } from './CartDrawer';
import { StoreClosed } from './StoreClosed';
import { ROUTES, APP_NAME } from '../constants';

export const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user, logout, isAdmin, loading: authLoading } = useAuth();
  const { isStoreOpen, loading: storeLoading } = useStore();
  const { toggleCart, totalItems } = useCart();
  const { theme, toggleTheme } = useTheme();
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = React.useState(false);
  const [animateCart, setAnimateCart] = useState(false);

  useEffect(() => {
    if (totalItems > 0) {
      setAnimateCart(true);
      const timer = setTimeout(() => setAnimateCart(false), 200);
      return () => clearTimeout(timer);
    }
  }, [totalItems]);

  const isActive = (path: string) => location.pathname === path;
  const isLoading = authLoading || storeLoading;

  const showClosedScreen = !isLoading && !isStoreOpen && !isAdmin;

  return (
    <div className="min-h-screen relative flex flex-col font-sans transition-colors duration-300 overflow-x-hidden">

      {/* --- Ambient Background Mesh --- */}
      <div className="fixed inset-0 z-[-1] overflow-hidden pointer-events-none">
        <div className="absolute top-0 left-1/4 w-96 h-96 bg-purple-400/30 dark:bg-purple-900/20 rounded-full mix-blend-multiply dark:mix-blend-screen filter blur-3xl opacity-70 animate-blob"></div>
        <div className="absolute top-0 right-1/4 w-96 h-96 bg-blue-400/30 dark:bg-blue-900/20 rounded-full mix-blend-multiply dark:mix-blend-screen filter blur-3xl opacity-70 animate-blob animation-delay-2000"></div>
        <div className="absolute -bottom-8 left-1/3 w-96 h-96 bg-pink-400/30 dark:bg-pink-900/20 rounded-full mix-blend-multiply dark:mix-blend-screen filter blur-3xl opacity-70 animate-blob animation-delay-4000"></div>
      </div>

      <header className="sticky top-4 mx-4 z-40 bg-white/40 dark:bg-black/40 backdrop-blur-xl border border-white/20 dark:border-white/10 rounded-2xl shadow-lg transition-all duration-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">

            {/* Logo */}
            <div className="flex-shrink-0 flex items-center">
              <Link to={ROUTES.HOME} className="font-serif font-bold text-2xl tracking-tighter text-black dark:text-white hover:opacity-70 transition-opacity">
                {APP_NAME}
              </Link>
            </div>

            {/* Desktop Nav */}
            <nav className="hidden md:flex space-x-12">
              <Link to={ROUTES.HOME} className={`text-sm tracking-wide uppercase font-medium transition-all duration-300 ${isActive(ROUTES.HOME) ? 'text-black dark:text-white font-bold' : 'text-gray-600 dark:text-gray-300 hover:text-black dark:hover:text-white'}`}>
                Menu
              </Link>
              {user && (
                <Link to={ROUTES.ORDERS} className={`text-sm tracking-wide uppercase font-medium transition-all duration-300 ${isActive(ROUTES.ORDERS) ? 'text-black dark:text-white font-bold' : 'text-gray-600 dark:text-gray-300 hover:text-black dark:hover:text-white'}`}>
                  Orders
                </Link>
              )}
              {isAdmin && (
                <Link to={ROUTES.ADMIN} className={`text-sm tracking-wide uppercase font-medium transition-all duration-300 ${isActive(ROUTES.ADMIN) ? 'text-black dark:text-white font-bold' : 'text-gray-600 dark:text-gray-300 hover:text-black dark:hover:text-white'}`}>
                  Dashboard
                </Link>
              )}
            </nav>

            {/* Actions */}
            <div className="flex items-center space-x-4 md:space-x-6">
              <button 
                onClick={toggleTheme} 
                className="p-2 text-gray-600 hover:text-black dark:text-gray-300 dark:hover:text-white transition-colors hover:bg-white/20 dark:hover:bg-white/10 rounded-full"
                aria-label="Toggle dark mode"
              >
                {theme === 'dark' ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
              </button>

              {!showClosedScreen && (
                <button 
                  onClick={toggleCart} 
                  className="relative p-2 text-black dark:text-white hover:bg-white/20 dark:hover:bg-white/10 rounded-full transition-all duration-300 group"
                  aria-label="Open cart"
                >
                  <ShoppingBag className="w-5 h-5 transition-transform duration-300 group-hover:scale-110" />
                  {totalItems > 0 && (
                    <span className={`absolute -top-1 -right-1 inline-flex items-center justify-center w-5 h-5 text-xs font-bold text-white bg-blue-600 rounded-full shadow-lg ${animateCart ? 'animate-pop' : ''}`}>
                      {totalItems}
                    </span>
                  )}
                </button>
              )}

              {user ? (
                <div className="relative group hidden md:block">
                  <button className="flex items-center space-x-2 text-sm font-medium text-black dark:text-white hover:bg-white/20 dark:hover:bg-white/10 p-2 rounded-full transition-colors">
                    <User className="w-5 h-5" />
                  </button>
                  <div className="absolute right-0 mt-4 w-48 bg-white/70 dark:bg-black/70 backdrop-blur-xl border border-white/20 dark:border-white/10 shadow-2xl rounded-xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 transform origin-top-right z-50">
                    <button onClick={() => logout()} className="w-full text-left px-6 py-3 text-sm text-black dark:text-white hover:bg-white/20 dark:hover:bg-white/10 rounded-xl flex items-center transition-colors duration-200">
                      <LogOut className="w-4 h-4 mr-2" /> Sign Out
                    </button>
                  </div>
                </div>
              ) : (
                <Link to={ROUTES.LOGIN} className="hidden md:inline-flex items-center justify-center px-6 py-2 border border-black/20 dark:border-white/20 bg-white/20 dark:bg-white/10 text-sm font-medium text-black dark:text-white hover:bg-white/40 dark:hover:bg-white/20 backdrop-blur-md transition-all duration-300 rounded-full uppercase tracking-wider shadow-sm">
                  Sign In
                </Link>
              )}

              {/* Mobile Menu Button */}
              <button className="md:hidden text-black dark:text-white transition-transform duration-300 active:scale-90" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
                 {isMobileMenuOpen ? <X className="w-6 h-6" /> : <MenuIcon className="w-6 h-6" />}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden bg-white/80 dark:bg-black/80 backdrop-blur-xl border-t border-white/20 dark:border-white/10 px-4 pt-2 pb-4 space-y-1 animate-fade-in absolute w-full left-0 rounded-b-2xl shadow-xl">
             <Link to={ROUTES.HOME} className="block px-3 py-4 text-lg font-serif font-bold text-black dark:text-white border-b border-black/5 dark:border-white/5 active:bg-black/5 transition-colors">Menu</Link>
             {user && <Link to={ROUTES.ORDERS} className="block px-3 py-4 text-lg font-serif font-bold text-black dark:text-white border-b border-black/5 dark:border-white/5 active:bg-black/5 transition-colors">My Orders</Link>}
             {isAdmin && <Link to={ROUTES.ADMIN} className="block px-3 py-4 text-lg font-serif font-bold text-black dark:text-white border-b border-black/5 dark:border-white/5 active:bg-black/5 transition-colors">Dashboard</Link>}
             {user ? (
               <button onClick={() => logout()} className="block w-full text-left px-3 py-4 text-lg font-serif font-medium text-gray-500 hover:text-black dark:hover:text-white transition-colors">Sign Out</button>
             ) : (
                <Link to={ROUTES.LOGIN} className="block px-3 py-4 text-lg font-serif font-bold text-black dark:text-white active:bg-black/5 transition-colors">Sign In</Link>
             )}
          </div>
        )}
      </header>

      {!isLoading && !isStoreOpen && isAdmin && (
        <div className="mx-auto mt-4 px-4">
           <div className="bg-red-500/20 backdrop-blur-md text-red-800 dark:text-red-200 text-center py-2 text-xs font-bold uppercase tracking-widest border border-red-500/30 rounded-full flex items-center justify-center gap-2 max-w-md mx-auto">
             <Lock className="w-3 h-3" /> Store is Closed (Admin Mode)
          </div>
        </div>
      )}

      <main className="flex-grow max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-12 relative z-10">
        {showClosedScreen ? <StoreClosed /> : children}
      </main>

      {!showClosedScreen && <CartDrawer />}

      <footer className="mt-auto py-8">
        <div className="max-w-7xl mx-auto px-4 flex flex-col items-center">
           <div className="bg-white/30 dark:bg-black/30 backdrop-blur-md px-8 py-4 rounded-full border border-white/20 dark:border-white/10 shadow-lg flex flex-col items-center">
              <span className="font-serif font-bold text-lg mb-1 text-black dark:text-white">{APP_NAME}</span>
              <div className="text-gray-600 dark:text-gray-300 text-xs font-mono uppercase tracking-widest">
                Quality Comes First
              </div>
           </div>
        </div>
      </footer>
    </div>
  );
};

import React, { useState } from 'react';
import { MenuItem } from '../types';
import { formatPrice } from '../utils/formatters';
import { Plus, Clock, Flame, Dumbbell, Scale } from 'lucide-react';
import { useCart } from '../contexts/CartContext';

interface Props {
  item: MenuItem;
}

export const MenuItemCard: React.FC<Props> = ({ item }) => {
  const { addToCart } = useCart();
  const [isAnimating, setIsAnimating] = useState(false);

  const handleAddToCart = () => {
    if (!item.isAvailable) return;

    addToCart(item);
    setIsAnimating(true);
    setTimeout(() => setIsAnimating(false), 200);
  };

  return (
    <div className={`group relative bg-white/40 dark:bg-black/40 backdrop-blur-md border border-white/40 dark:border-white/10 rounded-3xl overflow-hidden shadow-lg hover:shadow-2xl hover:scale-[1.02] transition-all duration-500 flex flex-col h-full ${!item.isAvailable ? 'opacity-50 grayscale' : ''} animate-fade-in`}>
      <div className="aspect-[4/3] w-full overflow-hidden relative">
        <img 
          src={item.imageUrl} 
          alt={item.name} 
          className="w-full h-full object-cover object-center group-hover:scale-110 transition-transform duration-700"
          loading="lazy"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent opacity-60"></div>

        {!item.isAvailable && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-[2px]">
            <span className="bg-white/20 backdrop-blur-md text-white text-xs font-bold px-4 py-2 uppercase tracking-widest border border-white/30 rounded-full">Sold Out</span>
          </div>
        )}

        {/* Fitness Goal Badge */}
        {item.fitnessGoal === 'muscle_gain' && (
          <div className="absolute top-3 left-3 bg-blue-500/80 text-white text-[10px] font-bold px-3 py-1.5 uppercase tracking-wider flex items-center backdrop-blur-md rounded-full border border-white/10 shadow-lg">
             <Dumbbell className="w-3 h-3 mr-1" /> Muscle Gain
          </div>
        )}
        {item.fitnessGoal === 'weight_loss' && (
          <div className="absolute top-3 left-3 bg-green-500/80 text-white text-[10px] font-bold px-3 py-1.5 uppercase tracking-wider flex items-center backdrop-blur-md rounded-full border border-white/10 shadow-lg">
             <Scale className="w-3 h-3 mr-1" /> Weight Loss
          </div>
        )}

        <div className="absolute bottom-3 right-3">
             <span className="bg-white/90 dark:bg-black/80 backdrop-blur-md text-black dark:text-white font-mono font-bold px-3 py-1 rounded-full shadow-lg border border-white/20">
                {formatPrice(item.price)}
             </span>
        </div>
      </div>

      <div className="p-6 flex flex-col flex-grow relative">
        <div className="mb-3">
          <h3 className="text-xl font-serif font-bold text-black dark:text-white leading-tight">{item.name}</h3>
        </div>

        <p className="text-sm text-gray-700 dark:text-gray-300 leading-relaxed mb-6 flex-grow font-medium">{item.description}</p>

        <div className="flex items-center justify-between pt-4 border-t border-black/5 dark:border-white/5 mt-auto">
          <div className="flex gap-4">
            <div className="flex items-center text-xs text-gray-600 dark:text-gray-400 font-bold font-mono uppercase tracking-wide">
                <Clock className="w-3 h-3 mr-2" />
                {item.preparationTime} MIN
            </div>
            {item.calories && (
                <div className="flex items-center text-xs text-orange-600 dark:text-orange-400 font-bold font-mono uppercase tracking-wide">
                    <Flame className="w-3 h-3 mr-1" />
                    {item.calories}
                </div>
            )}
          </div>

          <button 
            onClick={handleAddToCart}
            disabled={!item.isAvailable}
            className={`flex items-center justify-center w-10 h-10 rounded-full bg-black dark:bg-white text-white dark:text-black shadow-lg hover:scale-110 transition-all duration-300 disabled:opacity-0 disabled:cursor-not-allowed ${isAnimating ? 'animate-pop' : ''}`}
            aria-label={`Add ${item.name} to cart`}
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { useCart } from '../contexts/CartContext';
import { formatPrice } from '../utils/formatters';
import { X, Minus, Plus, ShoppingBag } from 'lucide-react';
import { useNavigate } from '../contexts/AuthContext';
import { ROUTES } from '../constants';

export const CartDrawer: React.FC = () => {
  const { items, quantities, updateQuantity, totalPrice, isCartOpen, toggleCart } = useCart();
  const navigate = useNavigate();

  if (!isCartOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-hidden">
      <div className="absolute inset-0 bg-black/30 backdrop-blur-sm transition-opacity" onClick={toggleCart} />

      <div className="absolute inset-y-4 right-4 max-w-md w-full flex pointer-events-none">
        <div className="pointer-events-auto w-full h-full bg-white/80 dark:bg-black/80 backdrop-blur-2xl border border-white/20 dark:border-white/10 flex flex-col animate-slide-in shadow-2xl rounded-3xl overflow-hidden">

          <div className="flex items-center justify-between px-8 py-6 border-b border-black/5 dark:border-white/5">
            <h2 className="text-2xl font-serif font-bold text-black dark:text-white flex items-center">
              Cart
              <span className="ml-3 px-2 py-1 bg-black/5 dark:bg-white/10 rounded-lg text-sm font-mono font-normal text-gray-600 dark:text-gray-300">[{items.length}]</span>
            </h2>
            <button onClick={toggleCart} className="text-black dark:text-white hover:bg-black/5 dark:hover:bg-white/10 p-2 rounded-full transition-all">
              <X className="w-6 h-6" />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-4">
            {items.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center space-y-6">
                <div className="w-24 h-24 bg-gray-100/50 dark:bg-gray-800/50 rounded-full flex items-center justify-center text-gray-400 dark:text-gray-500 backdrop-blur-sm">
                  <ShoppingBag className="w-10 h-10" />
                </div>
                <div>
                  <h3 className="text-lg font-serif font-bold text-black dark:text-white">Your cart is empty</h3>
                  <p className="text-sm text-gray-500 mt-2 max-w-[200px] mx-auto">Looks like you haven't added anything yet.</p>
                </div>
                <button onClick={toggleCart} className="px-6 py-3 bg-black/5 dark:bg-white/10 rounded-full text-sm font-bold text-black dark:text-white uppercase tracking-widest hover:bg-black/10 dark:hover:bg-white/20 transition-colors">
                  Browse Menu
                </button>
              </div>
            ) : (
              items.map((item) => (
                <div key={item.id} className="flex gap-4 p-4 bg-white/40 dark:bg-white/5 rounded-2xl border border-white/20 dark:border-white/5 shadow-sm">
                  <div className="w-20 h-20 flex-shrink-0 bg-gray-100 dark:bg-gray-900 rounded-xl overflow-hidden shadow-inner">
                    <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
                  </div>
                  <div className="flex-1 flex flex-col justify-between py-1">
                    <div className="flex justify-between items-start">
                      <h4 className="font-serif font-bold text-black dark:text-white text-lg leading-tight">{item.name}</h4>
                      <p className="text-sm font-mono font-bold text-black dark:text-white">{formatPrice(item.price)}</p>
                    </div>
                    <div className="flex items-center justify-between mt-2">
                      <div className="flex items-center bg-white/50 dark:bg-black/50 rounded-full p-1 border border-black/5 dark:border-white/10">
                        <button 
                          onClick={() => updateQuantity(item.id, -1)}
                          className="w-7 h-7 flex items-center justify-center bg-white dark:bg-zinc-800 rounded-full shadow-sm hover:scale-105 transition-transform text-black dark:text-white"
                        >
                          <Minus className="w-3 h-3" />
                        </button>
                        <span className="text-sm font-mono font-bold w-8 text-center text-black dark:text-white">{quantities[item.id]}</span>
                        <button 
                          onClick={() => updateQuantity(item.id, 1)}
                          className="w-7 h-7 flex items-center justify-center bg-black dark:bg-white rounded-full shadow-sm hover:scale-105 transition-transform text-white dark:text-black"
                        >
                          <Plus className="w-3 h-3" />
                        </button>
                      </div>
                      <p className="font-mono font-bold text-black dark:text-white">
                        {formatPrice(item.price * quantities[item.id])}
                      </p>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>

          {items.length > 0 && (
            <div className="border-t border-black/5 dark:border-white/5 p-6 space-y-6 bg-white/40 dark:bg-black/20 backdrop-blur-md">
              <div className="flex justify-between items-end">
                <p className="text-sm text-gray-500 uppercase tracking-widest font-bold">Total</p>
                <p className="font-serif font-bold text-4xl text-black dark:text-white">{formatPrice(totalPrice)}</p>
              </div>
              <button
                onClick={() => {
                  toggleCart();
                  navigate(ROUTES.CHECKOUT);
                }}
                className="w-full flex justify-center items-center px-8 py-5 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-2xl text-sm font-bold uppercase tracking-widest shadow-lg hover:shadow-blue-500/30 hover:scale-[1.02] transition-all"
              >
                Checkout
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { MenuItem, ProductCategory } from '../types';
import { getMenuItems, seedMenu, MOCK_MENU_ITEMS } from '../services/firestoreService';
import { MenuItemCard } from '../components/MenuItemCard';
import { Search } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { WelcomeToast } from '../components/WelcomeToast';

export const Home: React.FC = () => {
  const { user } = useAuth();
  const [items, setItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  const isInitialized = useRef(false);

  useEffect(() => {
    if (isInitialized.current) return;
    isInitialized.current = true;

    const fetchMenu = async () => {
      try {
        let data = await getMenuItems();

        if (data.length === 0) {
          if (user) {
            try {
              await seedMenu();
              data = await getMenuItems();
            } catch (e) {
              data = MOCK_MENU_ITEMS;
            }
          } else {
             data = MOCK_MENU_ITEMS;
          }
        }

        setItems(data);
      } catch (err) {
        console.error("Unexpected error in Home", err);
      } finally {
        setLoading(false);
      }
    };
    fetchMenu();
  }, [user]);

  const filteredItems = items.filter(item => {
    const matchesCategory = activeCategory === 'all' || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const categories = ['all', ...Object.values(ProductCategory)];

  if (loading) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 animate-pulse">
        {[1, 2, 3, 4, 5, 6].map(i => (
          <div key={i} className="h-96 bg-white/20 dark:bg-white/5 rounded-3xl backdrop-blur-md"></div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-12">
      {user && <WelcomeToast name={user.displayName || 'Guest'} />}

      {/* Header & Controls */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 pb-4">
        <div className="max-w-xl">
          <h1 className="text-5xl md:text-7xl font-serif font-bold text-black dark:text-white mb-4 leading-tight drop-shadow-sm">Menu</h1>
          <p className="text-gray-700 dark:text-gray-300 font-medium text-lg max-w-md">Curated selection of seasonal dishes focused on simplicity and quality ingredients.</p>
        </div>

        <div className="w-full md:w-auto">
          <div className="relative group">
             <div className="absolute -inset-0.5 bg-gradient-to-r from-pink-600 to-purple-600 rounded-full opacity-30 group-hover:opacity-100 blur transition duration-1000 group-hover:duration-200"></div>
             <div className="relative flex items-center gap-3 bg-white/60 dark:bg-black/60 backdrop-blur-xl border border-white/40 dark:border-white/10 rounded-full px-6 py-4 w-full md:w-80 shadow-lg">
                <Search className="w-5 h-5 text-gray-500 dark:text-gray-400" />
                <input 
                  type="text" 
                  placeholder="Search dishes..." 
                  className="outline-none text-base bg-transparent flex-grow placeholder:text-gray-500 dark:placeholder:text-gray-500 font-medium text-black dark:text-white"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
             </div>
          </div>
        </div>
      </div>

      {/* Categories */}
      <div className="flex flex-wrap gap-3">
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className={`px-6 py-3 rounded-full text-sm font-bold uppercase tracking-widest transition-all duration-300 shadow-sm hover:shadow-lg hover:scale-105 border ${
              activeCategory === cat 
                ? 'bg-black dark:bg-white text-white dark:text-black border-transparent' 
                : 'bg-white/40 dark:bg-black/40 backdrop-blur-md text-gray-600 dark:text-gray-300 border-white/40 dark:border-white/10 hover:bg-white/60 dark:hover:bg-white/10'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Grid */}
      {filteredItems.length > 0 ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-12">
          {filteredItems.map(item => (
            <MenuItemCard key={item.id} item={item} />
          ))}
        </div>
      ) : (
        <div className="text-center py-32 bg-white/20 dark:bg-black/20 backdrop-blur-md rounded-3xl border border-dashed border-gray-300 dark:border-gray-700">
            <>
              <p className="text-black dark:text-white font-serif text-2xl italic">No matches found.</p>
              <button 
                onClick={() => { setActiveCategory('all'); setSearchQuery(''); }}
                className="mt-6 text-xs font-bold uppercase tracking-widest border-b border-black dark:border-white pb-1 hover:text-gray-500 transition-colors"
              >
                Clear all filters
              </button>
            </>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { Navigate } from '../contexts/AuthContext';
import { ROUTES } from '../constants';
import { AlertTriangle } from 'lucide-react';
import { checkRateLimit, resetRateLimit, validatePassword, validateEmail } from '../utils/security';
import { UserRole } from '../types';

type Tab = 'login' | 'signup';

export const Login: React.FC = () => {
  const { user, signInWithGoogle, loginWithEmail, signupWithEmail, loading, error: authError } = useAuth();
  // We rely on the reactive redirect below.
  const [activeTab, setActiveTab] = useState<Tab>('login');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState('');

  if (loading) return null;

  // Automatic Redirect based on Role
  if (user) {
    return <Navigate to={user.role === UserRole.ADMIN ? ROUTES.ADMIN : ROUTES.HOME} replace />;
  }

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setLocalError('');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLocalError('');

    // --- Validation & Security Checks ---

    // 1. Rate Limiting for Login
    if (activeTab === 'login') {
      const rateLimit = checkRateLimit(email);
      if (!rateLimit.allowed) {
        setLocalError(`Too many attempts. Please try again in ${rateLimit.waitTimeMinutes} minutes.`);
        return;
      }
    }

    // 2. Email Validation
    if (!validateEmail(email)) {
       setLocalError("Please enter a valid email address.");
       return;
    }

    // 3. Password Validation (Strict check for signup)
    if (activeTab === 'signup') {
      const passValidation = validatePassword(password);
      if (!passValidation.isValid) {
        setLocalError(passValidation.message || "Invalid password.");
        return;
      }
      if (!name.trim()) {
        setLocalError("Name is required");
        return;
      }
    }

    setIsSubmitting(true);

    try {
      if (activeTab === 'signup') {
        await signupWithEmail(email, password, name);
      } else {
        await loginWithEmail(email, password);
        // Successful login, reset rate limit
        resetRateLimit(email);
      }
      // We do not manually navigate here. 
      // Successful auth will update the `user` object in context, triggering the redirect above.
    } catch (err: any) {
      // Don't reveal exactly why it failed to prevent enumeration (handled generically in AuthContext for user-not-found/wrong-password)
      setLocalError(err.message || "Action failed");
      setIsSubmitting(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLocalError('');
    try {
      await signInWithGoogle();
      // Redirect handled by reactive `user` check
    } catch (err: any) {
      setLocalError(err.message);
    }
  };

  const displayError = localError || authError;

  return (
    <div className="min-h-[70vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-md w-full bg-white/60 dark:bg-black/60 backdrop-blur-2xl p-8 shadow-2xl border border-white/40 dark:border-white/10 rounded-3xl transition-colors duration-300 relative overflow-hidden">

        {/* Glow effect */}
        <div className="absolute -top-20 -right-20 w-40 h-40 bg-blue-500/20 rounded-full blur-2xl"></div>
        <div className="absolute -bottom-20 -left-20 w-40 h-40 bg-purple-500/20 rounded-full blur-2xl"></div>

        <div className="text-center mb-12 relative z-10">
          <h1 className="text-4xl font-serif font-bold text-black dark:text-white mb-2">
            {activeTab === 'signup' ? 'Join Us' : 'Welcome Back'}
          </h1>
          <p className="text-gray-500 dark:text-gray-400 font-medium">
            {activeTab === 'signup' ? 'Create your account' : 'Access your account'}
          </p>
        </div>

        <div className="flex bg-gray-100/50 dark:bg-gray-800/50 p-1 rounded-xl mb-8 relative z-10">
          <button
            onClick={() => handleTabChange('login')}
            className={`flex-1 py-3 text-xs font-bold uppercase tracking-widest transition-all rounded-lg ${activeTab === 'login' ? 'bg-white dark:bg-black text-black dark:text-white shadow-md' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'}`}
          >
            Login
          </button>
          <button
            onClick={() => handleTabChange('signup')}
            className={`flex-1 py-3 text-xs font-bold uppercase tracking-widest transition-all rounded-lg ${activeTab === 'signup' ? 'bg-white dark:bg-black text-black dark:text-white shadow-md' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'}`}
          >
            Register
          </button>
        </div>

        <div className="relative z-10">
          {displayError && (
            <div className="mb-8 p-4 border border-red-200 dark:border-red-900/50 flex items-start text-left bg-red-50/80 dark:bg-red-900/20 rounded-xl backdrop-blur-sm">
              <AlertTriangle className="w-5 h-5 text-red-600 dark:text-red-400 mr-3 flex-shrink-0" />
              <p className="text-sm font-medium text-red-600 dark:text-red-300">{displayError}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {activeTab === 'signup' && (
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Full Name</label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full px-4 py-3 bg-white/50 dark:bg-black/50 border border-gray-200 dark:border-white/10 rounded-xl focus:border-blue-500 dark:focus:border-blue-500 text-black dark:text-white outline-none transition-all focus:ring-2 focus:ring-blue-500/20"
                  required
                />
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 bg-white/50 dark:bg-black/50 border border-gray-200 dark:border-white/10 rounded-xl focus:border-blue-500 dark:focus:border-blue-500 text-black dark:text-white outline-none transition-all focus:ring-2 focus:ring-blue-500/20 disabled:opacity-50"
                required
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Password</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 bg-white/50 dark:bg-black/50 border border-gray-200 dark:border-white/10 rounded-xl focus:border-blue-500 dark:focus:border-blue-500 text-black dark:text-white outline-none transition-all focus:ring-2 focus:ring-blue-500/20"
                required
                minLength={6}
              />
              {activeTab === 'signup' && (
                <p className="text-[10px] text-gray-500">Min 8 chars, 1 uppercase, 1 lowercase, 1 number.</p>
              )}
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-black dark:bg-white text-white dark:text-black py-4 font-bold uppercase tracking-widest hover:scale-[1.02] active:scale-[0.98] transition-all rounded-xl shadow-lg disabled:opacity-50 disabled:hover:scale-100 mt-4"
            >
              {isSubmitting ? 'Processing...' : activeTab === 'signup' ? 'Create Account' : 'Enter'}
            </button>
          </form>

          <div className="relative my-10 text-center">
            <span className="bg-transparent px-4 text-xs text-gray-400 uppercase tracking-widest relative z-10">or</span>
            <div className="absolute top-1/2 left-0 w-full border-t border-gray-300 dark:border-gray-700 -z-0"></div>
          </div>

          <button
            type="button"
            onClick={handleGoogleLogin}
            className="w-full flex items-center justify-center gap-3 bg-white/50 dark:bg-white/10 border border-gray-200 dark:border-white/10 py-4 text-sm font-bold uppercase tracking-widest hover:bg-white dark:hover:bg-white/20 transition-all text-black dark:text-white rounded-xl"
          >
            <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-5 h-5 bg-white rounded-full" />
            Continue with Google
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useCart } from '../contexts/CartContext';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, Navigate } from '../contexts/AuthContext';
import { createOrder } from '../services/firestoreService';
import { generateTimeSlots, formatTime, formatPrice } from '../utils/formatters';
import { ROUTES } from '../constants';
import { ArrowLeft, QrCode, AlertCircle } from 'lucide-react';
import { UPIPayment } from '../components/UPIPayment';
import { sanitizeInput } from '../utils/security';

export const Checkout: React.FC = () => {
  const { items, quantities, totalPrice, clearCart } = useCart();
  const { user } = useAuth();
  const navigate = useNavigate();

  // Checkout State
  const [selectedSlot, setSelectedSlot] = useState<Date | null>(null);
  const [step, setStep] = useState<'slot' | 'payment'>('slot');

  // Contact Details
  const [customerName, setCustomerName] = useState(user?.displayName || '');
  const [customerMobile, setCustomerMobile] = useState('');

  // Loading & Error State
  const [globalError, setGlobalError] = useState('');
  const [fieldErrors, setFieldErrors] = useState<{name?: string; mobile?: string; slot?: string}>({});

  if (!user) return <Navigate to={ROUTES.LOGIN} replace />;
  if (items.length === 0) return <Navigate to={ROUTES.HOME} replace />;

  const slots = generateTimeSlots();

  const handleProceedToPayment = () => {
    const errors: {name?: string; mobile?: string; slot?: string} = {};
    let hasError = false;

    if (!customerName.trim()) {
      errors.name = "Name is required.";
      hasError = true;
    }

    if (!customerMobile.trim()) {
      errors.mobile = "Mobile number is required.";
      hasError = true;
    } else if (customerMobile.replace(/\D/g, '').length < 10) {
      errors.mobile = "Please enter a valid mobile number (min 10 digits).";
      hasError = true;
    }

    if (!selectedSlot) {
      errors.slot = "Please select a pickup time.";
      hasError = true;
    }

    setFieldErrors(errors);

    if (hasError) {
      setGlobalError("Please correct the highlighted errors before proceeding.");
      return;
    }

    setGlobalError('');
    setStep('payment');
  };

  const handlePaymentSuccess = async (transactionId: string) => {
    if (!selectedSlot) return;

    // Sanitize inputs before sending to DB
    const safeName = sanitizeInput(customerName);
    const safeMobile = sanitizeInput(customerMobile);
    const safeTxId = sanitizeInput(transactionId);

    try {
      const slotId = selectedSlot.toISOString();
      await createOrder(
        user.uid,
        user.email,
        items,
        quantities,
        slotId,
        selectedSlot,
        safeTxId,
        safeName,
        safeMobile
      );
      // Order created successfully
      clearCart();
      navigate(ROUTES.ORDERS);
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("SLOT_FULL")) {
        setGlobalError("The selected time slot just filled up. Please select another.");
        setStep('slot');
      } else {
        setGlobalError("Failed to create order. Please try again.");
      }
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-4">
      {step === 'slot' && (
        <button onClick={() => navigate(-1)} className="flex items-center text-xs font-bold uppercase tracking-widest text-gray-600 dark:text-gray-400 hover:text-black dark:hover:text-white mb-8 transition-colors bg-white/20 dark:bg-black/20 px-4 py-2 rounded-full backdrop-blur-md">
          <ArrowLeft className="w-4 h-4 mr-2" /> Return to Menu
        </button>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-12 animate-fade-in relative">

        {/* LEFT COLUMN: Main Interaction Area */}
        <div className="lg:col-span-7 space-y-8">
          {step === 'slot' ? (
            <div className="bg-white/60 dark:bg-black/40 backdrop-blur-xl border border-white/40 dark:border-white/10 rounded-3xl p-8 shadow-xl">
              <div className="mb-8">
                <h2 className="text-3xl font-serif font-bold text-black dark:text-white mb-2">Checkout Details</h2>
                <p className="text-gray-600 dark:text-gray-400 text-sm">Review your details and schedule a pickup.</p>
              </div>

              <div className="space-y-10">

                {/* Contact Section */}
                <div className="space-y-6">
                  <h3 className="text-sm font-bold uppercase tracking-widest text-gray-500 border-b border-gray-200 dark:border-gray-700 pb-2">Contact Info</h3>
                  <div className="grid grid-cols-1 gap-6">
                    <div>
                      <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 dark:text-gray-400 mb-2">
                        NAME <span className="text-red-500">*</span>
                      </label>
                      <input 
                        type="text" 
                        value={customerName}
                        onChange={(e) => {
                          setCustomerName(e.target.value);
                          if (fieldErrors.name) setFieldErrors(prev => ({ ...prev, name: undefined }));
                        }}
                        className={`w-full bg-white/50 dark:bg-black/50 border rounded-xl p-4 text-black dark:text-white outline-none transition-all focus:ring-2 focus:ring-blue-500/20 ${
                          fieldErrors.name 
                            ? 'border-red-500' 
                            : 'border-gray-200 dark:border-white/10 focus:border-blue-500'
                        }`}
                        placeholder="Enter your name"
                      />
                      {fieldErrors.name && (
                        <p className="text-red-500 text-xs mt-2 flex items-center font-medium">
                          <AlertCircle className="w-3 h-3 mr-1" /> {fieldErrors.name}
                        </p>
                      )}
                    </div>
                    <div>
                      <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 dark:text-gray-400 mb-2">
                        MOBILE NUMBER <span className="text-red-500">*</span>
                      </label>
                      <input 
                        type="tel" 
                        value={customerMobile}
                        onChange={(e) => {
                          setCustomerMobile(e.target.value);
                          if (fieldErrors.mobile) setFieldErrors(prev => ({ ...prev, mobile: undefined }));
                        }}
                        className={`w-full bg-white/50 dark:bg-black/50 border rounded-xl p-4 text-black dark:text-white outline-none transition-all focus:ring-2 focus:ring-blue-500/20 ${
                          fieldErrors.mobile 
                            ? 'border-red-500' 
                            : 'border-gray-200 dark:border-white/10 focus:border-blue-500'
                        }`}
                        placeholder="e.g. 9876543210"
                      />
                      {fieldErrors.mobile && (
                        <p className="text-red-500 text-xs mt-2 flex items-center font-medium">
                          <AlertCircle className="w-3 h-3 mr-1" /> {fieldErrors.mobile}
                        </p>
                      )}
                    </div>
                  </div>
                </div>

                {/* Slot Section */}
                 <div className="space-y-6">
                   <div className="flex justify-between items-end border-b border-gray-200 dark:border-gray-700 pb-2">
                     <h3 className="text-sm font-bold uppercase tracking-widest text-gray-500">
                       Pickup Time <span className="text-red-500">*</span>
                     </h3>
                     {fieldErrors.slot && (
                       <span className="text-red-500 text-xs flex items-center font-medium">
                         <AlertCircle className="w-3 h-3 mr-1" /> {fieldErrors.slot}
                       </span>
                     )}
                   </div>
                   <div className={`grid grid-cols-3 sm:grid-cols-4 gap-3 transition-colors rounded-xl p-2 ${fieldErrors.slot ? 'bg-red-50/50 dark:bg-red-900/10 border border-red-500/30' : ''}`}>
                     {slots.map((slot) => (
                       <button
                         key={slot.toISOString()}
                         onClick={() => {
                           setSelectedSlot(slot);
                           if (fieldErrors.slot) setFieldErrors(prev => ({ ...prev, slot: undefined }));
                         }}
                         className={`px-2 py-4 text-sm font-mono transition-all rounded-xl border ${
                           selectedSlot === slot
                             ? 'bg-black dark:bg-white text-white dark:text-black border-transparent shadow-lg transform scale-105'
                             : 'bg-white/40 dark:bg-black/40 border-gray-200 dark:border-white/5 text-gray-500 hover:border-black dark:hover:border-white hover:text-black dark:hover:text-white'
                         }`}
                       >
                         {formatTime(slot)}
                       </button>
                     ))}
                   </div>
                 </div>

                 {globalError && (
                   <div className="text-red-600 dark:text-red-300 text-sm border border-red-200 dark:border-red-800 bg-red-50/80 dark:bg-red-900/20 p-4 rounded-xl flex items-start backdrop-blur-sm">
                     <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0" />
                     {globalError}
                   </div>
                 )}
              </div>
            </div>
          ) : (
            <div className="bg-white/60 dark:bg-black/40 backdrop-blur-xl border border-white/40 dark:border-white/10 rounded-3xl p-8 shadow-xl">
              <div className="mb-8">
                 <h2 className="text-3xl font-serif font-bold text-black dark:text-white">Payment</h2>
                 <p className="text-gray-500 mt-2">Scan QR code or pay via UPI App to complete order.</p>
              </div>
              <UPIPayment 
                amount={totalPrice} 
                onSuccess={handlePaymentSuccess}
                onCancel={() => setStep('slot')}
              />
            </div>
          )}
        </div>

        {/* RIGHT COLUMN: Order Summary */}
        <div className="lg:col-span-5 relative">
          <div className="lg:sticky lg:top-24 bg-white/60 dark:bg-black/60 backdrop-blur-2xl p-8 border border-white/40 dark:border-white/10 rounded-3xl shadow-2xl transition-all duration-300">
            <h3 className="text-xl font-serif font-bold text-black dark:text-white mb-6 border-b border-gray-200 dark:border-white/10 pb-4">Order Summary</h3>
            <ul className="space-y-4 mb-8">
              {items.map(item => (
                <li key={item.id} className="flex justify-between text-sm items-start">
                  <span className="text-black dark:text-white font-medium">
                    <span className="text-gray-500 dark:text-gray-400 mr-2 font-mono text-xs border border-gray-200 dark:border-white/10 px-1.5 py-0.5 rounded">{quantities[item.id]}x</span> 
                    {item.name}
                  </span>
                  <span className="font-mono text-gray-500 dark:text-gray-400">{formatPrice(item.price * quantities[item.id])}</span>
                </li>
              ))}
            </ul>

            <div className="flex justify-between items-center border-t border-dashed border-gray-300 dark:border-gray-700 pt-6 mb-8">
              <span className="font-bold text-black dark:text-white uppercase tracking-widest text-sm">Total Amount</span>
              <span className="font-bold font-mono text-3xl text-black dark:text-white">{formatPrice(totalPrice)}</span>
            </div>

            {step === 'slot' && (
              <button
                onClick={handleProceedToPayment}
                className="w-full flex justify-center items-center px-6 py-5 bg-black dark:bg-white text-white dark:text-black text-sm font-bold uppercase tracking-widest hover:scale-[1.02] transition-all shadow-lg rounded-xl group disabled:opacity-50 disabled:cursor-not-allowed"
              >
                  <>
                    Proceed to Payment <QrCode className="w-4 h-4 ml-2 group-hover:translate-x-1 transition-transform" />
                  </>
              </button>
            )}

            {step === 'slot' && !selectedSlot && (
              <p className="text-xs text-center text-gray-500 mt-4 uppercase tracking-wide">Please select a pickup time</p>
            )}

            {selectedSlot && (
              <div className="mt-6 flex items-center justify-center text-xs text-gray-600 dark:text-gray-300 uppercase tracking-widest bg-white/50 dark:bg-white/10 py-3 rounded-xl border border-white/20">
                 Pickup at <span className="text-black dark:text-white font-bold ml-2">{formatTime(selectedSlot)}</span>
              </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import { UPI_VPA, UPI_PAYEE_NAME, APP_NAME } from '../constants';
import { formatPrice } from '../utils/formatters';
import { Loader2, Send, Smartphone, Copy, Check } from 'lucide-react';

interface UPIPaymentProps {
  amount: number;
  onSuccess: (transactionId: string) => Promise<void>;
  onCancel: () => void;
}

export const UPIPayment: React.FC<UPIPaymentProps> = ({ amount, onSuccess, onCancel }) => {
  const [transactionId, setTransactionId] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [copied, setCopied] = useState(false);

  // Generate a unique transaction reference for this session
  const transactionRef = useMemo(() => `T${Date.now()}`, []);

  // Construct UPI URL
  const upiUrl = `upi://pay?pa=${UPI_VPA}&pn=${encodeURIComponent(UPI_PAYEE_NAME)}&am=${amount.toFixed(2)}&cu=INR&tn=${encodeURIComponent(`Order at ${APP_NAME}`)}&tr=${transactionRef}`;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!transactionId.trim()) {
      setError("Please enter the Transaction ID / UTR");
      return;
    }

    setError('');
    setIsSubmitting(true);
    try {
      await onSuccess(transactionId);
    } catch (err) {
      setError("Failed to process order. Please try again.");
      setIsSubmitting(false);
    }
  };

  const copyVpa = () => {
    navigator.clipboard.writeText(UPI_VPA);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="animate-fade-in space-y-8">

      <div className="bg-white/50 dark:bg-white/5 p-8 rounded-2xl border border-white/20 dark:border-white/10 shadow-sm transition-colors duration-300">
        <h3 className="font-serif font-bold text-xl mb-8 text-center text-black dark:text-white">Scan or Click to Pay</h3>

        <div className="flex flex-col items-center justify-center space-y-8">
          <div className="bg-white p-4 rounded-2xl shadow-lg relative">
             <QRCodeSVG value={upiUrl} size={200} />
          </div>

          <div className="w-full space-y-3 md:hidden">
            <a 
              href={upiUrl}
              className="flex items-center justify-center w-full px-6 py-4 bg-black dark:bg-white text-white dark:text-black font-bold uppercase tracking-widest text-sm hover:opacity-90 rounded-xl transition-all shadow-md"
            >
              <Smartphone className="w-4 h-4 mr-2" /> Pay via UPI App
            </a>
            <p className="text-[10px] text-center text-gray-500">
              If the button doesn't work, copy the UPI ID below and pay manually.
            </p>
          </div>

          <div className="text-center w-full">
            <p className="text-4xl font-mono font-bold text-black dark:text-white mb-2">{formatPrice(amount)}</p>
            <div className="flex items-center justify-center gap-2 mb-4">
              <span className="text-xs text-gray-500 dark:text-gray-400 uppercase tracking-widest">To: {UPI_PAYEE_NAME}</span>
            </div>

            <button 
              onClick={copyVpa}
              className="flex items-center justify-center gap-2 text-xs font-mono bg-white/50 dark:bg-black/50 border border-gray-200 dark:border-white/10 px-6 py-3 rounded-full mx-auto hover:bg-white dark:hover:bg-white/10 transition-colors text-black dark:text-gray-300 shadow-sm"
            >
              {UPI_VPA}
              {copied ? <Check className="w-3 h-3 text-green-600" /> : <Copy className="w-3 h-3 text-gray-500" />}
            </button>
          </div>
        </div>

        <div className="mt-8 pt-6 border-t border-black/5 dark:border-white/5">
          <p className="text-xs text-center text-gray-500 dark:text-gray-400 leading-relaxed max-w-sm mx-auto">
             1. Open PhonePe, Google Pay, or Paytm.<br/>
             2. Scan QR code OR Click 'Pay via UPI App'.<br/>
             3. Complete payment and <strong>copy the UTR / Transaction ID.</strong><br/>
             4. Paste the ID below to confirm.
          </p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="bg-white/30 dark:bg-black/30 border border-white/20 dark:border-white/5 p-6 rounded-2xl backdrop-blur-md">
        <h4 className="text-black dark:text-white font-serif font-bold mb-4">Verification</h4>

        <div className="space-y-4">
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 dark:text-gray-400 mb-2">Transaction ID / UTR</label>
            <input 
              type="text" 
              value={transactionId}
              onChange={(e) => setTransactionId(e.target.value)}
              placeholder="e.g. 308572189..."
              className="w-full bg-white/50 dark:bg-black/50 border border-gray-200 dark:border-white/10 px-4 py-3 rounded-xl focus:border-blue-500 dark:focus:border-blue-500 text-black dark:text-white outline-none transition-all focus:ring-2 focus:ring-blue-500/20 font-mono"
            />
            {error && <p className="text-red-600 dark:text-red-400 text-xs mt-2 font-medium">{error}</p>}
          </div>

          <div className="flex gap-4 pt-2">
            <button
              type="button"
              onClick={onCancel}
              disabled={isSubmitting}
              className="flex-1 py-4 text-sm font-bold uppercase tracking-widest text-gray-500 hover:text-black dark:hover:text-white transition-colors border border-transparent hover:border-gray-300 dark:hover:border-gray-700 rounded-xl"
            >
              Back
            </button>
            <button
              type="submit"
              disabled={!transactionId || isSubmitting}
              className="flex-1 bg-black dark:bg-white text-white dark:text-black py-4 text-sm font-bold uppercase tracking-widest hover:scale-[1.02] transition-all rounded-xl shadow-lg disabled:opacity-50 flex justify-center items-center"
            >
              {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <>Submit Order <Send className="w-4 h-4 ml-2" /></>}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { subscribeToUserOrders } from '../services/firestoreService';
import { Order, OrderStatus } from '../types';
import { formatPrice, formatDate, formatTime } from '../utils/formatters';
import { Loader2, Package, Clock, CheckCircle, Utensils, Check, XCircle, ArrowRight } from 'lucide-react';

const StatusBadge: React.FC<{ status: OrderStatus }> = ({ status }) => {
  const configs = {
    [OrderStatus.PENDING]: {
      style: 'border border-dashed border-gray-400 text-gray-500 dark:border-gray-500 dark:text-gray-400',
      label: 'Pending Approval',
      icon: <Clock className="w-3 h-3 mr-2 animate-pulse" />
    },
    [OrderStatus.CONFIRMED]: {
      style: 'bg-black text-white dark:bg-white dark:text-black shadow-lg',
      label: 'Accepted',
      icon: <CheckCircle className="w-3 h-3 mr-2" />
    },
    [OrderStatus.PREPARING]: {
      style: 'bg-blue-100 text-blue-800 dark:bg-blue-900/40 dark:text-blue-200 border border-blue-200 dark:border-blue-800 animate-pulse',
      label: 'Preparing',
      icon: <Loader2 className="w-3 h-3 mr-2 animate-spin" />
    },
    [OrderStatus.READY]: {
      style: 'bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-200 border border-green-200 dark:border-green-800 shadow-xl transform scale-105',
      label: 'Ready for Pickup',
      icon: <Utensils className="w-3 h-3 mr-2" />
    },
    [OrderStatus.COMPLETED]: {
      style: 'bg-gray-100 dark:bg-white/10 text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-white/10',
      label: 'Completed',
      icon: <Check className="w-3 h-3 mr-2" />
    },
    [OrderStatus.CANCELLED]: {
      style: 'text-red-700 dark:text-red-300 border border-dashed border-red-200 dark:border-red-900/50 bg-red-50 dark:bg-red-900/10',
      label: 'Cancelled',
      icon: <XCircle className="w-3 h-3 mr-2" />
    },
  };

  const config = configs[status];

  return (
    <span className={`inline-flex items-center px-4 py-1.5 text-xs font-bold uppercase tracking-widest transition-all duration-300 rounded-full ${config.style}`}>
      {config.icon}
      {config.label}
    </span>
  );
};

const OrderProgressBar: React.FC<{ status: OrderStatus }> = ({ status }) => {
  let progress = 0;
  let animate = false;

  switch (status) {
    case OrderStatus.PENDING: progress = 10; break;
    case OrderStatus.CONFIRMED: progress = 30; break;
    case OrderStatus.PREPARING: progress = 70; animate = true; break;
    case OrderStatus.READY: progress = 100; break;
    default: return null;
  }

  return (
    <div className="w-full h-1.5 bg-gray-200 dark:bg-gray-800 mt-6 overflow-hidden rounded-full">
      <div 
        className={`h-full bg-gradient-to-r from-blue-500 to-purple-600 transition-all duration-1000 ease-out rounded-full shadow-[0_0_10px_rgba(59,130,246,0.5)] ${animate ? 'animate-[pulse_2s_infinite]' : ''}`}
        style={{ width: `${progress}%` }}
      />
    </div>
  );
};

export const Orders: React.FC = () => {
  const { user } = useAuth();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) return;
    const unsubscribe = subscribeToUserOrders(user.uid, (data) => {
      setOrders(data);
      setLoading(false);
    });
    return () => unsubscribe();
  }, [user]);

  if (loading) return <div className="flex justify-center py-32"><Loader2 className="animate-spin w-8 h-8 text-black dark:text-white" /></div>;

  const activeOrders = orders.filter(o => [OrderStatus.PENDING, OrderStatus.CONFIRMED, OrderStatus.PREPARING, OrderStatus.READY].includes(o.status));
  const pastOrders = orders.filter(o => [OrderStatus.COMPLETED, OrderStatus.CANCELLED].includes(o.status));

  return (
    <div className="max-w-4xl mx-auto space-y-16">

      {/* ACTIVE ORDERS SECTION */}
      {activeOrders.length > 0 && (
        <div className="space-y-8 animate-fade-in">
          <div className="flex items-end justify-between border-b border-black/10 dark:border-white/10 pb-4">
            <h2 className="text-3xl font-serif font-bold text-black dark:text-white flex items-center">
              <span className="w-3 h-3 bg-green-500 rounded-full mr-4 animate-pulse shadow-[0_0_10px_#22c55e]"></span>
              Live Kitchen Status
            </h2>
            <span className="px-3 py-1 bg-white/50 dark:bg-white/10 rounded-full text-xs font-mono font-bold text-gray-600 dark:text-gray-300 border border-white/20">{activeOrders.length} ACTIVE</span>
          </div>

          <div className="grid gap-8">
            {activeOrders.map(order => (
              <div 
                key={order.id} 
                className={`relative p-8 transition-all duration-500 animate-fade-in backdrop-blur-xl rounded-3xl border ${
                  order.status === OrderStatus.READY 
                    ? 'bg-white/80 dark:bg-white/10 shadow-2xl border-white/50 dark:border-white/20 scale-[1.02]' 
                    : 'bg-white/40 dark:bg-black/40 border-white/40 dark:border-white/10 shadow-lg'
                }`}
              >
                {/* Header */}
                <div className="flex flex-col md:flex-row justify-between md:items-start gap-4 mb-6">
                  <div>
                    <div className="flex items-center gap-3 mb-2">
                       <StatusBadge status={order.status} />
                       <span className="font-mono text-xs text-gray-500 dark:text-gray-400">#{order.id.slice(0, 6)}</span>
                    </div>
                    <div className="text-4xl font-serif font-bold mt-2 text-black dark:text-white drop-shadow-sm">
                      {formatTime(order.scheduledTime)}
                    </div>
                    <p className="text-xs uppercase tracking-widest mt-1 text-gray-500 dark:text-gray-400 font-bold">
                      Estimated Pickup
                    </p>
                  </div>

                  <div className="text-right">
                    <p className="text-2xl font-mono font-bold text-black dark:text-white">
                      {formatPrice(order.totalAmount)}
                    </p>
                    <p className="text-xs uppercase tracking-widest text-gray-500 dark:text-gray-400">
                      {order.items.length} Items
                    </p>
                  </div>
                </div>

                {/* Items */}
                <div className="border-t border-black/5 dark:border-white/5 pt-6">
                  <ul className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-2">
                    {order.items.map((item, idx) => (
                      <li key={idx} className="flex justify-between text-sm items-center py-1 text-gray-800 dark:text-gray-200">
                        <span className="font-medium">
                          <span className="font-mono mr-3 text-gray-500 dark:text-gray-400 font-bold bg-white/50 dark:bg-white/10 px-1.5 rounded">
                            {item.quantity}x
                          </span> 
                          {item.name}
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>

                {/* Progress Bar */}
                {order.status !== OrderStatus.READY && <OrderProgressBar status={order.status} />}

                {/* Ready Banner */}
                {order.status === OrderStatus.READY && (
                  <div className="mt-6 bg-black text-white dark:bg-white dark:text-black text-center py-3 text-sm font-bold uppercase tracking-[0.2em] flex items-center justify-center gap-2 animate-pop rounded-xl shadow-lg">
                    <Utensils className="w-4 h-4" /> Ready for Pickup
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* PAST ORDERS SECTION */}
      <div className="space-y-8 animate-fade-in" style={{ animationDelay: '0.1s' }}>
        <div className="border-b border-black/10 dark:border-white/10 pb-4">
          <h2 className="text-2xl font-serif font-bold text-gray-500 dark:text-gray-400">History</h2>
        </div>

        {pastOrders.length === 0 && activeOrders.length === 0 ? (
          <div className="text-center py-24 border border-dashed border-gray-300 dark:border-gray-700 bg-white/20 dark:bg-white/5 rounded-3xl backdrop-blur-sm">
            <Package className="w-10 h-10 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-serif font-bold text-black dark:text-white">No orders yet</h3>
            <p className="text-gray-500 mt-2 text-sm">Your order history will appear here.</p>
          </div>
        ) : (
          <div className="grid gap-4">
            {pastOrders.map(order => (
              <div key={order.id} className="bg-white/40 dark:bg-black/40 backdrop-blur-md border border-white/40 dark:border-white/10 rounded-2xl p-6 flex flex-col md:flex-row justify-between items-center gap-4 group hover:bg-white/60 dark:hover:bg-black/60 transition-all duration-300 hover:shadow-lg hover:scale-[1.01]">
                 <div className="flex items-center gap-6 w-full md:w-auto">
                    <StatusBadge status={order.status} />
                    <div>
                      <div className="text-black dark:text-white font-serif font-bold text-lg">
                        {formatDate(order.scheduledTime)}
                      </div>
                      <div className="text-gray-500 dark:text-gray-400 text-xs font-mono">
                        #{order.id.slice(0, 8)} • {formatTime(order.scheduledTime)}
                      </div>
                    </div>
                 </div>

                 <div className="flex items-center gap-8 w-full md:w-auto justify-between md:justify-end">
                    <div className="text-right">
                       <span className="block text-black dark:text-white font-mono font-bold">{formatPrice(order.totalAmount)}</span>
                       <span className="block text-gray-500 text-xs">{order.items.length} items</span>
                    </div>
                    <ArrowRight className="w-5 h-5 text-gray-400 group-hover:translate-x-1 transition-transform duration-300" />
                 </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
