};

import React, { useEffect, useState, useRef } from 'react';
import { MenuItem, ProductCategory } from '../types';
import { getMenuItems, seedMenu, MOCK_MENU_ITEMS } from '../services/firestoreService';
import { MenuItemCard } from '../components/MenuItemCard';
import { Search } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { WelcomeToast } from '../components/WelcomeToast';

export const Home: React.FC = () => {
  const { user } = useAuth();
  const [items, setItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  const isInitialized = useRef(false);

  useEffect(() => {
    if (isInitialized.current) return;
    isInitialized.current = true;

    const fetchMenu = async () => {
      try {
        let data = await getMenuItems();

        if (data.length === 0) {
          if (user) {
            try {
              await seedMenu();
              data = await getMenuItems();
            } catch (e) {
              data = MOCK_MENU_ITEMS;
            }
          } else {
             data = MOCK_MENU_ITEMS;
          }
        }

        setItems(data);
      } catch (err) {
        console.error("Unexpected error in Home", err);
      } finally {
        setLoading(false);
      }
    };
    fetchMenu();
  }, [user]);

  const filteredItems = items.filter(item => {
    const matchesCategory = activeCategory === 'all' || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const categories = ['all', ...Object.values(ProductCategory)];

  if (loading) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 animate-pulse">
        {[1, 2, 3, 4, 5, 6].map(i => (
          <div key={i} className="h-96 bg-gray-200 dark:bg-gray-900 border border-gray-300 dark:border-gray-800"></div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-12">
      {user && <WelcomeToast name={user.displayName || 'Guest'} />}

      {/* Header & Controls */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 border-b border-black dark:border-white pb-8 transition-colors duration-300">
        <div className="max-w-xl">
          <h1 className="text-5xl font-serif font-bold text-black dark:text-white mb-4 leading-tight transition-colors duration-300">Menu</h1>
          <p className="text-gray-600 dark:text-gray-400 font-light text-lg">Curated selection of seasonal dishes focused on simplicity and quality ingredients.</p>
        </div>

        <div className="w-full md:w-auto">
          <div className="flex items-center gap-3 border-b border-gray-300 dark:border-gray-700 pb-2 focus-within:border-black dark:focus-within:border-white transition-colors w-full md:w-64">
            <Search className="w-4 h-4 text-black dark:text-white" />
            <input 
              type="text" 
              placeholder="SEARCH DISHES" 
              className="outline-none text-sm bg-transparent flex-grow placeholder:text-gray-500 font-medium tracking-wide text-black dark:text-white"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* Categories */}
      <div className="flex flex-wrap gap-4">
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className={`px-6 py-2 text-sm font-bold uppercase tracking-widest transition-all border ${
              activeCategory === cat 
                ? 'bg-black dark:bg-white text-white dark:text-black border-black dark:border-white' 
                : 'bg-white dark:bg-black text-gray-500 dark:text-gray-500 border-gray-200 dark:border-gray-800 hover:border-black dark:hover:border-white hover:text-black dark:hover:text-white'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Grid */}
      {filteredItems.length > 0 ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-12">
          {filteredItems.map(item => (
            <MenuItemCard key={item.id} item={item} />
          ))}
        </div>
      ) : (
        <div className="text-center py-32 border border-dashed border-gray-300 dark:border-gray-800">
            <>
              <p className="text-black dark:text-white font-serif text-2xl italic">No matches found.</p>
              <button 
                onClick={() => { setActiveCategory('all'); setSearchQuery(''); }}
                className="mt-6 text-xs font-bold uppercase tracking-widest border-b border-black dark:border-white pb-1 hover:text-gray-500 hover:border-gray-500 transition-colors"
              >
                Clear all filters
              </button>
            </>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { Navigate } from '../contexts/AuthContext';
import { ROUTES } from '../constants';
import { AlertTriangle } from 'lucide-react';
import { checkRateLimit, resetRateLimit, validatePassword, validateEmail } from '../utils/security';
import { UserRole } from '../types';

type Tab = 'login' | 'signup';

export const Login: React.FC = () => {
  const { user, signInWithGoogle, loginWithEmail, signupWithEmail, loading, error: authError } = useAuth();
  // We rely on the reactive redirect below.
  const [activeTab, setActiveTab] = useState<Tab>('login');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState('');

  if (loading) return null;

  // Automatic Redirect based on Role
  if (user) {
    return <Navigate to={user.role === UserRole.ADMIN ? ROUTES.ADMIN : ROUTES.HOME} replace />;
  }

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setLocalError('');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLocalError('');

    // --- Validation & Security Checks ---

    // 1. Rate Limiting for Login
    if (activeTab === 'login') {
      const rateLimit = checkRateLimit(email);
      if (!rateLimit.allowed) {
        setLocalError(`Too many attempts. Please try again in ${rateLimit.waitTimeMinutes} minutes.`);
        return;
      }
    }

    // 2. Email Validation
    if (!validateEmail(email)) {
       setLocalError("Please enter a valid email address.");
       return;
    }

    // 3. Password Validation (Strict check for signup)
    if (activeTab === 'signup') {
      const passValidation = validatePassword(password);
      if (!passValidation.isValid) {
        setLocalError(passValidation.message || "Invalid password.");
        return;
      }
      if (!name.trim()) {
        setLocalError("Name is required");
        return;
      }
    }

    setIsSubmitting(true);

    try {
      if (activeTab === 'signup') {
        await signupWithEmail(email, password, name);
      } else {
        await loginWithEmail(email, password);
        // Successful login, reset rate limit
        resetRateLimit(email);
      }
      // We do not manually navigate here. 
      // Successful auth will update the `user` object in context, triggering the redirect above.
    } catch (err: any) {
      // Don't reveal exactly why it failed to prevent enumeration (handled generically in AuthContext for user-not-found/wrong-password)
      setLocalError(err.message || "Action failed");
      setIsSubmitting(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLocalError('');
    try {
      await signInWithGoogle();
      // Redirect handled by reactive `user` check
    } catch (err: any) {
      setLocalError(err.message);
    }
  };

  const displayError = localError || authError;

  return (
    <div className="min-h-[70vh] flex items-center justify-center px-4 py-12">
      <div className="max-w-md w-full bg-white dark:bg-black p-8 shadow-2xl border border-gray-100 dark:border-gray-800 transition-colors duration-300">

        <div className="text-center mb-12">
          <h1 className="text-4xl font-serif font-bold text-black dark:text-white mb-2">
            {activeTab === 'signup' ? 'Join Us' : 'Welcome Back'}
          </h1>
          <p className="text-gray-500 font-light">
            {activeTab === 'signup' ? 'Create your account' : 'Access your account'}
          </p>
        </div>

        <div className="flex border-b border-gray-200 dark:border-gray-800 mb-8">
          <button
            onClick={() => handleTabChange('login')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'login' ? 'text-black dark:text-white border-b-2 border-black dark:border-white' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'}`}
          >
            Login
          </button>
          <button
            onClick={() => handleTabChange('signup')}
            className={`flex-1 pb-4 text-xs font-bold uppercase tracking-widest transition-colors ${activeTab === 'signup' ? 'text-black dark:text-white border-b-2 border-black dark:border-white' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'}`}
          >
            Register
          </button>
        </div>

        <div>
          {displayError && (
            <div className="mb-8 p-4 border border-red-200 dark:border-white flex items-start text-left bg-red-50 dark:bg-gray-900">
              <AlertTriangle className="w-5 h-5 text-red-600 dark:text-white mr-3 flex-shrink-0" />
              <p className="text-sm font-medium text-red-600 dark:text-white">{displayError}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {activeTab === 'signup' && (
              <div className="space-y-2">
                <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Full Name</label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full px-4 py-3 bg-gray-50 dark:bg-black border border-gray-300 dark:border-gray-700 focus:border-black dark:focus:border-white text-black dark:text-white outline-none transition-colors"
                  required
                />
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 bg-gray-50 dark:bg-black border border-gray-300 dark:border-gray-700 focus:border-black dark:focus:border-white text-black dark:text-white outline-none transition-colors disabled:bg-gray-100 dark:disabled:bg-gray-900 disabled:text-gray-500"
                required
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold uppercase tracking-widest text-gray-500">Password</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 bg-gray-50 dark:bg-black border border-gray-300 dark:border-gray-700 focus:border-black dark:focus:border-white text-black dark:text-white outline-none transition-colors"
                required
                minLength={6}
              />
              {activeTab === 'signup' && (
                <p className="text-[10px] text-gray-500">Min 8 chars, 1 uppercase, 1 lowercase, 1 number.</p>
              )}
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-black dark:bg-white text-white dark:text-black py-4 font-bold uppercase tracking-widest hover:bg-gray-800 dark:hover:bg-gray-200 transition-colors disabled:opacity-50 mt-4"
            >
              {isSubmitting ? 'Processing...' : activeTab === 'signup' ? 'Create Account' : 'Enter'}
            </button>
          </form>

          <div className="relative my-10 text-center">
            <span className="bg-white dark:bg-black px-4 text-xs text-gray-400 uppercase tracking-widest">or</span>
            <div className="absolute top-1/2 left-0 w-full border-t border-gray-200 dark:border-gray-800 -z-10"></div>
          </div>

          <button
            type="button"
            onClick={handleGoogleLogin}
            className="w-full flex items-center justify-center gap-3 border border-gray-300 dark:border-white py-4 text-sm font-bold uppercase tracking-widest hover:bg-gray-50 dark:hover:bg-white hover:text-black dark:hover:text-black transition-all text-black dark:text-white"
          >
            <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" className="w-5 h-5 bg-white rounded-full" />
            Continue with Google
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useCart } from '../contexts/CartContext';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, Navigate } from '../contexts/AuthContext';
import { createOrder } from '../services/firestoreService';
import { generateTimeSlots, formatTime, formatPrice } from '../utils/formatters';
import { ROUTES } from '../constants';
import { ArrowLeft, QrCode, AlertCircle } from 'lucide-react';
import { UPIPayment } from '../components/UPIPayment';
import { sanitizeInput } from '../utils/security';

export const Checkout: React.FC = () => {
  const { items, quantities, totalPrice, clearCart } = useCart();
  const { user } = useAuth();
  const navigate = useNavigate();

  // Checkout State
  const [selectedSlot, setSelectedSlot] = useState<Date | null>(null);
  const [step, setStep] = useState<'slot' | 'payment'>('slot');

  // Contact Details
  const [customerName, setCustomerName] = useState(user?.displayName || '');
  const [customerMobile, setCustomerMobile] = useState('');

  // Loading & Error State
  const [globalError, setGlobalError] = useState('');
  const [fieldErrors, setFieldErrors] = useState<{name?: string; mobile?: string; slot?: string}>({});

  if (!user) return <Navigate to={ROUTES.LOGIN} replace />;
  if (items.length === 0) return <Navigate to={ROUTES.HOME} replace />;

  const slots = generateTimeSlots();

  const handleProceedToPayment = () => {
    const errors: {name?: string; mobile?: string; slot?: string} = {};
    let hasError = false;

    if (!customerName.trim()) {
      errors.name = "Name is required.";
      hasError = true;
    }

    if (!customerMobile.trim()) {
      errors.mobile = "Mobile number is required.";
      hasError = true;
    } else if (customerMobile.replace(/\D/g, '').length < 10) {
      errors.mobile = "Please enter a valid mobile number (min 10 digits).";
      hasError = true;
    }

    if (!selectedSlot) {
      errors.slot = "Please select a pickup time.";
      hasError = true;
    }

    setFieldErrors(errors);

    if (hasError) {
      setGlobalError("Please correct the highlighted errors before proceeding.");
      return;
    }

    setGlobalError('');
    setStep('payment');
  };

  const handlePaymentSuccess = async (transactionId: string) => {
    if (!selectedSlot) return;

    // Sanitize inputs before sending to DB
    const safeName = sanitizeInput(customerName);
    const safeMobile = sanitizeInput(customerMobile);
    const safeTxId = sanitizeInput(transactionId);

    try {
      const slotId = selectedSlot.toISOString();
      await createOrder(
        user.uid,
        user.email,
        items,
        quantities,
        slotId,
        selectedSlot,
        safeTxId,
        safeName,
        safeMobile
      );
      // Order created successfully
      clearCart();
      navigate(ROUTES.ORDERS);
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("SLOT_FULL")) {
        setGlobalError("The selected time slot just filled up. Please select another.");
        setStep('slot');
      } else {
        setGlobalError("Failed to create order. Please try again.");
      }
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-4">
      {step === 'slot' && (
        <button onClick={() => navigate(-1)} className="flex items-center text-xs font-bold uppercase tracking-widest text-gray-500 hover:text-black dark:hover:text-white mb-8 transition-colors">
          <ArrowLeft className="w-4 h-4 mr-2" /> Return to Menu
        </button>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-24 animate-fade-in relative">

        {/* LEFT COLUMN: Main Interaction Area */}
        <div className="lg:col-span-7 space-y-12">
          {step === 'slot' ? (
            <>
              <div>
                <h2 className="text-3xl font-serif font-bold text-black dark:text-white mb-2">Checkout Details</h2>
                <p className="text-gray-500 text-sm">Review your details and schedule a pickup.</p>
              </div>

              <div className="space-y-10">

                {/* Contact Section */}
                <div className="space-y-6">
                  <h3 className="text-sm font-bold uppercase tracking-widest text-gray-500 border-b border-gray-200 dark:border-gray-800 pb-2">Contact Info</h3>
                  <div className="space-y-6">
                    <div>
                      <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">
                        NAME <span className="text-red-500">*</span>
                      </label>
                      <input 
                        type="text" 
                        value={customerName}
                        onChange={(e) => {
                          setCustomerName(e.target.value);
                          if (fieldErrors.name) setFieldErrors(prev => ({ ...prev, name: undefined }));
                        }}
                        className={`w-full bg-gray-50 dark:bg-black border p-4 text-black dark:text-white outline-none transition-colors ${
                          fieldErrors.name 
                            ? 'border-red-500 focus:border-red-500' 
                            : 'border-gray-300 dark:border-gray-700 focus:border-black dark:focus:border-white'
                        }`}
                        placeholder="Enter your name"
                      />
                      {fieldErrors.name && (
                        <p className="text-red-500 text-xs mt-2 flex items-center font-medium">
                          <AlertCircle className="w-3 h-3 mr-1" /> {fieldErrors.name}
                        </p>
                      )}
                    </div>
                    <div>
                      <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">
                        MOBILE NUMBER <span className="text-red-500">*</span>
                      </label>
                      <input 
                        type="tel" 
                        value={customerMobile}
                        onChange={(e) => {
                          setCustomerMobile(e.target.value);
                          if (fieldErrors.mobile) setFieldErrors(prev => ({ ...prev, mobile: undefined }));
                        }}
                        className={`w-full bg-gray-50 dark:bg-black border p-4 text-black dark:text-white outline-none transition-colors ${
                          fieldErrors.mobile 
                            ? 'border-red-500 focus:border-red-500' 
                            : 'border-gray-300 dark:border-gray-700 focus:border-black dark:focus:border-white'
                        }`}
                        placeholder="e.g. 9876543210"
                      />
                      {fieldErrors.mobile && (
                        <p className="text-red-500 text-xs mt-2 flex items-center font-medium">
                          <AlertCircle className="w-3 h-3 mr-1" /> {fieldErrors.mobile}
                        </p>
                      )}
                    </div>
                  </div>
                </div>

                {/* Slot Section */}
                 <div className="space-y-6">
                   <div className="flex justify-between items-end border-b border-gray-200 dark:border-gray-800 pb-2">
                     <h3 className="text-sm font-bold uppercase tracking-widest text-gray-500">
                       Pickup Time <span className="text-red-500">*</span>
                     </h3>
                     {fieldErrors.slot && (
                       <span className="text-red-500 text-xs flex items-center font-medium">
                         <AlertCircle className="w-3 h-3 mr-1" /> {fieldErrors.slot}
                       </span>
                     )}
                   </div>
                   <div className={`grid grid-cols-3 sm:grid-cols-4 gap-3 p-1 transition-colors rounded-sm ${fieldErrors.slot ? 'bg-red-50 dark:bg-red-900/10 border border-dashed border-red-500/50' : ''}`}>
                     {slots.map((slot) => (
                       <button
                         key={slot.toISOString()}
                         onClick={() => {
                           setSelectedSlot(slot);
                           if (fieldErrors.slot) setFieldErrors(prev => ({ ...prev, slot: undefined }));
                         }}
                         className={`px-2 py-4 text-sm font-mono transition-all border ${
                           selectedSlot === slot
                             ? 'bg-black dark:bg-white text-white dark:text-black border-black dark:border-white shadow-md transform scale-105'
                             : 'bg-white dark:bg-black border-gray-200 dark:border-gray-800 text-gray-500 hover:border-black dark:hover:border-white hover:text-black dark:hover:text-white'
                         }`}
                       >
                         {formatTime(slot)}
                       </button>
                     ))}
                   </div>
                 </div>

                 {globalError && (
                   <div className="text-red-600 dark:text-red-400 text-sm border border-red-200 dark:border-red-900 bg-red-50 dark:bg-red-900/20 p-4 flex items-start">
                     <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0" />
                     {globalError}
                   </div>
                 )}
              </div>
            </>
          ) : (
            <>
              <div className="mb-8">
                 <h2 className="text-3xl font-serif font-bold text-black dark:text-white">Payment</h2>
                 <p className="text-gray-500 mt-2">Scan QR code or pay via UPI App to complete order.</p>
              </div>
              <UPIPayment 
                amount={totalPrice} 
                onSuccess={handlePaymentSuccess}
                onCancel={() => setStep('slot')}
              />
            </>
          )}
        </div>

        {/* RIGHT COLUMN: Order Summary */}
        <div className="lg:col-span-5 relative">
          <div className="lg:sticky lg:top-24 bg-white dark:bg-black p-8 border border-gray-200 dark:border-white shadow-xl dark:shadow-none transition-colors duration-300">
            <h3 className="text-xl font-serif font-bold text-black dark:text-white mb-6 border-b border-gray-200 dark:border-white pb-4">Order Summary</h3>
            <ul className="space-y-4 mb-8">
              {items.map(item => (
                <li key={item.id} className="flex justify-between text-sm items-start">
                  <span className="text-black dark:text-white font-medium">
                    <span className="text-gray-500 mr-2 font-mono text-xs border border-gray-200 dark:border-gray-800 px-1.5 py-0.5 rounded">{quantities[item.id]}x</span> 
                    {item.name}
                  </span>
                  <span className="font-mono text-gray-500 dark:text-gray-400">{formatPrice(item.price * quantities[item.id])}</span>
                </li>
              ))}
            </ul>

            <div className="flex justify-between items-center border-t border-dashed border-gray-300 dark:border-gray-700 pt-6 mb-8">
              <span className="font-bold text-black dark:text-white uppercase tracking-widest text-sm">Total Amount</span>
              <span className="font-bold font-mono text-2xl text-black dark:text-white">{formatPrice(totalPrice)}</span>
            </div>

            {step === 'slot' && (
              <button
                onClick={handleProceedToPayment}
                className="w-full flex justify-center items-center px-6 py-5 bg-black dark:bg-white text-white dark:text-black text-sm font-bold uppercase tracking-widest hover:bg-gray-800 dark:hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed transition-all group"
              >
                  <>
                    Proceed to Payment <QrCode className="w-4 h-4 ml-2 group-hover:translate-x-1 transition-transform" />
                  </>
              </button>
            )}

            {step === 'slot' && !selectedSlot && (
              <p className="text-xs text-center text-gray-500 mt-4 uppercase tracking-wide">Please select a pickup time</p>
            )}

            {selectedSlot && (
              <div className="mt-6 flex items-center justify-center text-xs text-gray-500 uppercase tracking-widest bg-gray-100 dark:bg-zinc-900 py-3 rounded-sm">
                 Pickup at <span className="text-black dark:text-white font-bold ml-2">{formatTime(selectedSlot)}</span>
              </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import { UPI_VPA, UPI_PAYEE_NAME, APP_NAME } from '../constants';
import { formatPrice } from '../utils/formatters';
import { Loader2, Send, Smartphone, Copy, Check } from 'lucide-react';

interface UPIPaymentProps {
  amount: number;
  onSuccess: (transactionId: string) => Promise<void>;
  onCancel: () => void;
}

export const UPIPayment: React.FC<UPIPaymentProps> = ({ amount, onSuccess, onCancel }) => {
  const [transactionId, setTransactionId] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [copied, setCopied] = useState(false);

  // Generate a unique transaction reference for this session
  const transactionRef = useMemo(() => `T${Date.now()}`, []);

  // Construct UPI URL
  const upiUrl = `upi://pay?pa=${UPI_VPA}&pn=${encodeURIComponent(UPI_PAYEE_NAME)}&am=${amount.toFixed(2)}&cu=INR&tn=${encodeURIComponent(`Order at ${APP_NAME}`)}&tr=${transactionRef}`;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!transactionId.trim()) {
      setError("Please enter the Transaction ID / UTR");
      return;
    }

    setError('');
    setIsSubmitting(true);
    try {
      await onSuccess(transactionId);
    } catch (err) {
      setError("Failed to process order. Please try again.");
      setIsSubmitting(false);
    }
  };

  const copyVpa = () => {
    navigator.clipboard.writeText(UPI_VPA);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="animate-fade-in space-y-8">

      <div className="bg-white dark:bg-zinc-900 text-black dark:text-white p-8 border border-gray-200 dark:border-zinc-800 shadow-sm transition-colors duration-300">
        <h3 className="font-serif font-bold text-xl mb-8 text-center">Scan or Click to Pay</h3>

        <div className="flex flex-col items-center justify-center space-y-8">
          <div className="bg-white p-4 border-2 border-dashed border-gray-300 rounded-lg relative">
             <QRCodeSVG value={upiUrl} size={200} />
          </div>

          <div className="w-full space-y-3 md:hidden">
            <a 
              href={upiUrl}
              className="flex items-center justify-center w-full px-6 py-4 bg-black dark:bg-white text-white dark:text-black font-bold uppercase tracking-widest text-sm hover:bg-gray-800 dark:hover:bg-gray-200 transition-colors"
            >
              <Smartphone className="w-4 h-4 mr-2" /> Pay via UPI App
            </a>
            <p className="text-[10px] text-center text-gray-500">
              If the button doesn't work, copy the UPI ID below and pay manually.
            </p>
          </div>

          <div className="text-center w-full">
            <p className="text-3xl font-mono font-bold text-black dark:text-white">{formatPrice(amount)}</p>
            <div className="flex items-center justify-center gap-2 mt-2">
              <span className="text-xs text-gray-500 uppercase tracking-widest">To: {UPI_PAYEE_NAME}</span>
            </div>

            <button 
              onClick={copyVpa}
              className="mt-4 flex items-center justify-center gap-2 text-xs font-mono bg-gray-100 dark:bg-black border border-gray-200 dark:border-gray-800 px-4 py-2 rounded-full mx-auto hover:bg-gray-200 dark:hover:bg-zinc-900 transition-colors text-black dark:text-gray-300"
            >
              {UPI_VPA}
              {copied ? <Check className="w-3 h-3 text-green-600" /> : <Copy className="w-3 h-3 text-gray-500" />}
            </button>
          </div>
        </div>

        <div className="mt-8 pt-6 border-t border-gray-100 dark:border-zinc-800">
          <p className="text-xs text-center text-gray-500 leading-relaxed max-w-sm mx-auto">
             1. Open PhonePe, Google Pay, or Paytm.<br/>
             2. Scan QR code OR Click 'Pay via UPI App'.<br/>
             3. Complete payment and <strong>copy the UTR / Transaction ID.</strong><br/>
             4. Paste the ID below to confirm.
          </p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="bg-gray-50 dark:bg-black border border-gray-200 dark:border-white p-6 transition-colors duration-300">
        <h4 className="text-black dark:text-white font-serif font-bold mb-4">Verification</h4>

        <div className="space-y-4">
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Transaction ID / UTR</label>
            <input 
              type="text" 
              value={transactionId}
              onChange={(e) => setTransactionId(e.target.value)}
              placeholder="e.g. 308572189..."
              className="w-full bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 px-4 py-3 focus:border-black dark:focus:border-white text-black dark:text-white outline-none transition-colors font-mono"
            />
            {error && <p className="text-red-600 dark:text-red-500 text-xs mt-2 font-medium">{error}</p>}
          </div>

          <div className="flex gap-4 pt-2">
            <button
              type="button"
              onClick={onCancel}
              disabled={isSubmitting}
              className="flex-1 py-4 text-sm font-bold uppercase tracking-widest text-gray-500 hover:text-black dark:hover:text-white transition-colors border border-transparent hover:border-gray-300 dark:hover:border-gray-700"
            >
              Back
            </button>
            <button
              type="submit"
              disabled={!transactionId || isSubmitting}
              className="flex-1 bg-black dark:bg-white text-white dark:text-black py-4 text-sm font-bold uppercase tracking-widest hover:bg-gray-800 dark:hover:bg-gray-200 transition-colors disabled:opacity-50 flex justify-center items-center"
            >
              {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <>Submit Order <Send className="w-4 h-4 ml-2" /></>}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

