## STEP 8: DATABASE & API OPTIMIZATION

### 8.1 Optimize Firestore Queries

```typescript
// ❌ BAD: Fetches all orders, then filters in JS
const allOrders = await getDocs(collection(db, 'orders'))
const userOrders = allOrders.docs.filter(doc => doc.data().userId === userId)

// ✅ GOOD: Query only what you need
const q = query(
  collection(db, 'orders'),
  where('userId', '==', userId),
  orderBy('createdAt', 'desc'),
  limit(20) // Pagination!
)
const userOrders = await getDocs(q)
```

### 8.2 Use Firestore Indexes

```javascript
// Create composite indexes for complex queries
// Firebase Console → Firestore → Indexes

// Example index:
// Collection: orders
// Fields: userId (Ascending), createdAt (Descending)
```

### 8.3 Batch Firestore Reads

```typescript
// ❌ BAD: Multiple individual reads
const user = await getDoc(doc(db, 'users', userId))
const profile = await getDoc(doc(db, 'profiles', userId))
const settings = await getDoc(doc(db, 'settings', userId))

// ✅ GOOD: Single batch read
const batch = [
  getDoc(doc(db, 'users', userId)),
  getDoc(doc(db, 'profiles', userId)),
  getDoc(doc(db, 'settings', userId)),
]
const [user, profile, settings] = await Promise.all(batch)
```

### 8.4 Implement Pagination

```typescript
// First page
const first = query(
  collection(db, 'projects'),
  orderBy('createdAt', 'desc'),
  limit(20)
)
const firstPage = await getDocs(first)

// Next page
const lastVisible = firstPage.docs[firstPage.docs.length - 1]
const next = query(
  collection(db, 'projects'),
  orderBy('createdAt', 'desc'),
  startAfter(lastVisible),
  limit(20)
)
const nextPage = await getDocs(next)
```

### 8.5 Cache API Responses

```typescript
// API route with caching
export async function GET(request: Request) {
  const data = await fetchData()

  return Response.json(data, {
    headers: {
      'Cache-Control': 'public, s-maxage=3600, stale-while-revalidate=86400'
    }
  })
}
```

