import React, { useEffect, useState, useRef } from 'react';
import { MenuItem, ProductCategory } from '../types';
import { getMenuItems, seedMenu, MOCK_MENU_ITEMS, getUserFavorites } from '../services/firestoreService';
import { MenuItemCard } from '../components/MenuItemCard';
import { Search, Heart, Leaf } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { WelcomeToast } from '../components/WelcomeToast';

export const Home: React.FC = () => {
  const { user } = useAuth();
  const [items, setItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  // Filters
  const [showVegOnly, setShowVegOnly] = useState(false);
  const [userFavorites, setUserFavorites] = useState<Set<string>>(new Set());

  const isInitialized = useRef(false);

  // Fetch Menu
  useEffect(() => {
    if (isInitialized.current) return;
    isInitialized.current = true;

    const fetchMenu = async () => {
      try {
        let data = await getMenuItems();

        if (data.length === 0) {
          if (user) {
            try {
              await seedMenu();
              data = await getMenuItems();
            } catch (e) {
              data = MOCK_MENU_ITEMS;
            }
          } else {
             data = MOCK_MENU_ITEMS;
          }
        }

        setItems(data);
      } catch (err) {
        console.error("Unexpected error in Home", err);
      } finally {
        setLoading(false);
      }
    };
    fetchMenu();
  }, [user]);

  // Fetch Favorites
  useEffect(() => {
    if (user) {
      getUserFavorites(user.uid).then(favs => {
        setUserFavorites(new Set(favs));
      });
    } else {
      setUserFavorites(new Set());
    }
  }, [user]);

  const toggleFavoriteLocal = (itemId: string) => {
    setUserFavorites(prev => {
      const next = new Set(prev);
      if (next.has(itemId)) {
        next.delete(itemId);
      } else {
        next.add(itemId);
      }
      return next;
    });
  };

  const filteredItems = items.filter(item => {
    const matchesCategory = activeCategory === 'all' || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(searchQuery.toLowerCase());

    // Veg Filter
    if (showVegOnly && !item.isVegetarian) return false;

    return matchesCategory && matchesSearch;
  });

  const categories = ['all', ...Object.values(ProductCategory)];

  if (loading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-pulse">
        {[1, 2, 3, 4, 5, 6].map(i => (
          <div key={i} className="h-80 bg-gray-100 rounded-xl"></div>
        ))}
      </div>
    );
  }

  return (
    <div>
      {user && <WelcomeToast name={user.displayName || 'Guest'} />}

      {/* Menu Header */}
      <div className="mb-8">
        <h2 className="text-4xl font-bold text-gray-900 mb-2">Menu</h2>
        <p className="text-gray-600 text-lg">
          Curated selection of dishes focused on quality and taste.
        </p>
      </div>

      {/* Controls Container */}
      <div className="space-y-6 mb-8">

        {/* Veg Toggle */}
        <div className="flex items-center">
           <button
             onClick={() => setShowVegOnly(!showVegOnly)}
             className={`inline-flex items-center gap-2 px-4 py-2 rounded-full border transition-all ${
               showVegOnly 
                 ? 'bg-green-50 border-green-500 text-green-700' 
                 : 'bg-white border-gray-300 text-gray-700 hover:bg-gray-50'
             }`}
           >
             <Leaf className="w-4 h-4" />
             Veg Only
           </button>
        </div>

        {/* Search Bar */}
        <div className="relative">
          <input
            type="text"
            placeholder="Search dishes..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full px-4 py-3 pl-10 bg-gray-100 border-transparent rounded-lg focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
          />
          <Search className="w-5 h-5 absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
        </div>

        {/* Category Pills */}
        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-5 py-2 rounded-full whitespace-nowrap text-sm font-medium transition-colors ${
                activeCategory === cat 
                  ? 'bg-gray-900 text-white shadow-md' 
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              {cat.charAt(0).toUpperCase() + cat.slice(1)}
            </button>
          ))}
        </div>
      </div>

      {/* Grid */}
      {filteredItems.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredItems.map((item, index) => (
            <MenuItemCard 
              key={item.id} 
              item={item} 
              isFavorite={userFavorites.has(item.id)}
              onToggleFavorite={toggleFavoriteLocal}
              priority={index < 4}
            />
          ))}
        </div>
      ) : (
        <div className="text-center py-24 bg-gray-50 rounded-xl border border-dashed border-gray-200">
            <h3 className="text-lg font-bold text-gray-900">No dishes found</h3>
            <p className="text-gray-500 mt-1">Try adjusting your filters</p>
            <button 
              onClick={() => { setActiveCategory('all'); setSearchQuery(''); setShowVegOnly(false); }}
              className="mt-4 text-blue-600 font-medium hover:underline"
            >
              Clear all filters
            </button>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { MenuItem } from '../types';
import { formatPrice } from '../utils/formatters';
import { Plus, Clock, Flame, Dumbbell, Scale, Heart } from 'lucide-react';
import { useCart } from '../contexts/CartContext';
import { useAuth } from '../contexts/AuthContext';
import { toggleFavorite } from '../services/firestoreService';

interface Props {
  item: MenuItem;
  isFavorite?: boolean;
  onToggleFavorite?: (id: string) => void;
  priority?: boolean;
}

export const MenuItemCard: React.FC<Props> = ({ item, isFavorite = false, onToggleFavorite, priority = false }) => {
  const { addToCart } = useCart();
  const { user } = useAuth();
  const [isAnimating, setIsAnimating] = useState(false);
  const [isHeartAnimating, setIsHeartAnimating] = useState(false);

  const handleAddToCart = () => {
    if (!item.isAvailable) return;

    addToCart(item);
    setIsAnimating(true);
    setTimeout(() => setIsAnimating(false), 200);
  };

  const handleFavoriteClick = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!user) return;

    setIsHeartAnimating(true);
    setTimeout(() => setIsHeartAnimating(false), 300);

    if (onToggleFavorite) {
      onToggleFavorite(item.id);
    }

    try {
      await toggleFavorite(user.uid, item.id, isFavorite);
    } catch (error) {
      console.error("Failed to toggle favorite", error);
    }
  };

  return (
    <div className={`bg-white rounded-xl overflow-hidden shadow-sm hover:shadow-lg transition-all duration-300 border border-gray-200 flex flex-col h-full ${!item.isAvailable ? 'opacity-75 grayscale' : ''}`}>
      <div className="relative h-48 bg-gray-100 overflow-hidden">
        <img 
          src={item.imageUrl} 
          alt={item.name} 
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
          loading={priority ? "eager" : "lazy"}
          decoding="async"
        />

        {!item.isAvailable && (
          <div className="absolute inset-0 flex items-center justify-center bg-white/60 backdrop-blur-[1px]">
            <span className="bg-gray-900 text-white text-xs font-bold px-3 py-1 rounded-full uppercase tracking-wide shadow-sm">Sold Out</span>
          </div>
        )}

        {/* Fitness Goal Badge */}
        {item.fitnessGoal === 'muscle_gain' && (
          <div className="absolute top-2 left-2 bg-blue-600/90 text-white text-[10px] font-bold px-2 py-1 rounded shadow-sm flex items-center">
             <Dumbbell className="w-3 h-3 mr-1" /> Muscle Gain
          </div>
        )}
        {item.fitnessGoal === 'weight_loss' && (
          <div className="absolute top-2 left-2 bg-green-600/90 text-white text-[10px] font-bold px-2 py-1 rounded shadow-sm flex items-center">
             <Scale className="w-3 h-3 mr-1" /> Weight Loss
          </div>
        )}

        {/* Favorite Button */}
        {user && (
          <button 
            onClick={handleFavoriteClick}
            className="absolute top-2 right-2 p-2 bg-white/90 rounded-full hover:scale-110 transition-transform shadow-sm"
          >
            <Heart className={`w-4 h-4 transition-colors ${isFavorite ? 'fill-red-500 text-red-500' : 'text-gray-400'} ${isHeartAnimating ? 'animate-pop' : ''}`} />
