        <div className="flex justify-between items-start mb-2">
          <div className="flex-1 pr-4">
             <div className="flex items-center gap-2 mb-1">
                {item.isVegetarian !== undefined && (
                  <span className={`inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-bold uppercase ${item.isVegetarian ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
