                  </span>
                )}
                {item.isSpicy && <Flame className="w-3 h-3 text-orange-500" />}
             </div>
             <h3 className="text-lg font-bold text-gray-900 leading-tight">{item.name}</h3>
          </div>
        </div>

        <p className="text-sm text-gray-500 leading-relaxed mb-4 flex-grow line-clamp-2">{item.description}</p>

        <div className="flex items-center justify-between mt-auto">
          <span className="text-xl font-bold text-gray-900">{formatPrice(item.price)}</span>

          <button 
            onClick={handleAddToCart}
            disabled={!item.isAvailable}
            className={`flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all duration-200 font-medium text-sm disabled:opacity-50 disabled:cursor-not-allowed ${isAnimating ? 'scale-95 bg-blue-700' : ''}`}
          >
            {isAnimating ? 'Added' : 'Add'}
          </button>
        </div>
      </div>
    </div>
  );
};

