              {!showClosedScreen && (
                <button 
                  onClick={toggleCart} 
                  className="relative p-2 text-black dark:text-white hover:text-gray-600 dark:hover:text-gray-300 transition-colors duration-300 group"
                  aria-label="Open cart"
