import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MenuItem } from '../types';
import { Sparkles, X, Send, User, Bot, Loader2 } from 'lucide-react';

interface AIChatProps {
  menuItems: MenuItem[];
}

interface Message {
  role: 'user' | 'model';
  text: string;
}

export const AIChat: React.FC<AIChatProps> = ({ menuItems }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: "Welcome to Noir. I know the menu by heart. What are you in the mood for?" }
  ]);
  const [input, setInput] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isThinking) return;

    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput('');
    setIsThinking(true);

    try {
      // Prepare context about the menu
      const menuContext = menuItems.map(item => 
        `${item.name} (${item.category}): ₹${item.price}. ${item.description}. ${item.isVegetarian ? 'Veg' : 'Non-Veg'}. ${item.fitnessGoal || ''}. ${!item.isAvailable ? '[SOLD OUT]' : ''}`
      ).join('\n');

      const systemPrompt = `You are the concierge for 'Noir Canteen'. 
      Your tone is sophisticated, minimalist, and helpful.
      Here is the current menu status:
      ${menuContext}

      Rules:
      1. Only recommend items from the list above.
      2. If a user asks for something not on the menu, politely suggest a similar alternative.
      3. Keep answers short (max 2 sentences).
      4. Mention price when recommending.
      5. Don't recommend sold-out items unless asked specifically.
      `;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // We combine system prompt and history for a simple stateless request (or use chat session)
      // For this implementation, we'll do a single turn with context to save tokens/complexity, 
      // but feeding previous 2 messages for continuity.
      const recentHistory = messages.slice(-2).map(m => `${m.role === 'user' ? 'Customer' : 'You'}: ${m.text}`).join('\n');

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `${systemPrompt}\n\nConversation History:\n${recentHistory}\nCustomer: ${userMsg}\nYou:`,
      });

      const reply = response.text || "I apologize, I'm having trouble connecting to the kitchen.";

      setMessages(prev => [...prev, { role: 'model', text: reply }]);
    } catch (error) {
      console.error(error);
      setMessages(prev => [...prev, { role: 'model', text: "Connection interruption. Please try again." }]);
    } finally {
      setIsThinking(false);
    }
  };

  return (
    <>
      {/* Trigger Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`fixed bottom-6 right-6 z-50 p-4 rounded-full shadow-2xl transition-all duration-300 hover:scale-110 ${isOpen ? 'rotate-90 bg-white text-black' : 'bg-black text-white dark:bg-white dark:text-black'}`}
      >
        {isOpen ? <X className="w-6 h-6" /> : <Sparkles className="w-6 h-6" />}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-24 right-6 z-50 w-80 md:w-96 bg-white dark:bg-zinc-900 border border-gray-200 dark:border-zinc-800 shadow-2xl rounded-2xl overflow-hidden flex flex-col animate-slide-in origin-bottom-right max-h-[500px]">

          {/* Header */}
          <div className="bg-black dark:bg-white p-4 flex items-center gap-3">
            <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
            <span className="font-serif font-bold text-white dark:text-black">Noir Concierge</span>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50 dark:bg-black">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${msg.role === 'user' ? 'bg-gray-200 dark:bg-zinc-800' : 'bg-black dark:bg-white text-white dark:text-black'}`}>
                  {msg.role === 'user' ? <User className="w-4 h-4 text-gray-600 dark:text-gray-400" /> : <Sparkles className="w-4 h-4" />}
                </div>
                <div className={`p-3 text-sm max-w-[80%] rounded-2xl ${
                  msg.role === 'user' 
                    ? 'bg-white dark:bg-zinc-900 border border-gray-200 dark:border-zinc-800 text-black dark:text-white rounded-tr-none' 
                    : 'bg-black dark:bg-white text-white dark:text-black rounded-tl-none'
                }`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isThinking && (
              <div className="flex gap-3">
                 <div className="w-8 h-8 rounded-full bg-black dark:bg-white flex items-center justify-center">
                    <Sparkles className="w-4 h-4 text-white dark:text-black" />
                 </div>
                 <div className="bg-black dark:bg-white p-4 rounded-2xl rounded-tl-none">
                    <Loader2 className="w-4 h-4 animate-spin text-white dark:text-black" />
                 </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input */}
          <form onSubmit={handleSend} className="p-2 bg-white dark:bg-zinc-900 border-t border-gray-100 dark:border-zinc-800">
            <div className="relative">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask for recommendations..."
                className="w-full bg-gray-100 dark:bg-black border-none rounded-full py-3 pl-4 pr-12 text-sm focus:ring-1 focus:ring-black dark:focus:ring-white outline-none dark:text-white transition-all"
              />
              <button 
                type="submit" 
                disabled={!input.trim() || isThinking}
                className="absolute right-1 top-1 p-2 bg-black dark:bg-white text-white dark:text-black rounded-full hover:opacity-80 disabled:opacity-50 transition-all"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
          </form>
        </div>
      )}
    </>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { MenuItem, ProductCategory } from '../types';
import { getMenuItems, seedMenu, MOCK_MENU_ITEMS, getUserFavorites } from '../services/firestoreService';
import { MenuItemCard } from '../components/MenuItemCard';
import { Search, Heart, Leaf } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { WelcomeToast } from '../components/WelcomeToast';
import { AIChat } from '../components/AIChat';

export const Home: React.FC = () => {
  const { user } = useAuth();
  const [items, setItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  // New Filter States
  const [showVegOnly, setShowVegOnly] = useState(false);
  const [showFavoritesOnly, setShowFavoritesOnly] = useState(false);
  const [userFavorites, setUserFavorites] = useState<Set<string>>(new Set());

  const isInitialized = useRef(false);

  // Fetch Menu
  useEffect(() => {
    if (isInitialized.current) return;
    isInitialized.current = true;

    const fetchMenu = async () => {
      try {
        let data = await getMenuItems();

        if (data.length === 0) {
          if (user) {
            try {
              await seedMenu();
              data = await getMenuItems();
            } catch (e) {
              data = MOCK_MENU_ITEMS;
            }
          } else {
             data = MOCK_MENU_ITEMS;
          }
        }

        setItems(data);
      } catch (err) {
        console.error("Unexpected error in Home", err);
      } finally {
        setLoading(false);
      }
    };
    fetchMenu();
  }, [user]);

  // Fetch Favorites
  useEffect(() => {
    if (user) {
      getUserFavorites(user.uid).then(favs => {
        setUserFavorites(new Set(favs));
      });
    } else {
      setUserFavorites(new Set());
    }
  }, [user]);

  const toggleFavoriteLocal = (itemId: string) => {
    setUserFavorites(prev => {
      const next = new Set(prev);
      if (next.has(itemId)) {
        next.delete(itemId);
      } else {
        next.add(itemId);
      }
      return next;
    });
  };

  const filteredItems = items.filter(item => {
    const matchesCategory = activeCategory === 'all' || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(searchQuery.toLowerCase());

    // Veg Filter
    if (showVegOnly && !item.isVegetarian) return false;

    // Favorites Filter
    if (showFavoritesOnly && !userFavorites.has(item.id)) return false;

    return matchesCategory && matchesSearch;
  });

  const categories = ['all', ...Object.values(ProductCategory)];

  if (loading) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 animate-pulse">
        {[1, 2, 3, 4, 5, 6].map(i => (
          <div key={i} className="h-96 bg-gray-200 dark:bg-gray-900 border border-gray-300 dark:border-gray-800"></div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-12 relative">
      {user && <WelcomeToast name={user.displayName || 'Guest'} />}

      {/* AIChat Integration - Passes full menu context */}
      <AIChat menuItems={items} />

      {/* Header & Controls */}
      <div className="flex flex-col xl:flex-row xl:items-end justify-between gap-8 border-b border-black dark:border-white pb-8 transition-colors duration-300">
        <div className="max-w-xl">
          <h1 className="text-5xl font-serif font-bold text-black dark:text-white mb-4 leading-tight transition-colors duration-300">Menu</h1>
          <p className="text-gray-600 dark:text-gray-400 font-light text-lg">Curated selection of seasonal dishes focused on simplicity and quality ingredients.</p>
        </div>

        <div className="w-full xl:w-auto flex flex-col md:flex-row gap-6 md:items-center">
          {/* Smart Filters */}
          <div className="flex gap-3">
             <button
               onClick={() => setShowVegOnly(!showVegOnly)}
               className={`flex items-center gap-2 px-4 py-2 text-xs font-bold uppercase tracking-widest border transition-all ${
                 showVegOnly 
                   ? 'bg-green-600 text-white border-green-600' 
                   : 'bg-transparent text-gray-500 border-gray-300 dark:border-gray-700 hover:border-green-600 hover:text-green-600'
               }`}
             >
               <Leaf className="w-3 h-3" /> Veg Only
             </button>

             {user && (
               <button
                 onClick={() => setShowFavoritesOnly(!showFavoritesOnly)}
                 className={`flex items-center gap-2 px-4 py-2 text-xs font-bold uppercase tracking-widest border transition-all ${
                   showFavoritesOnly 
                     ? 'bg-red-600 text-white border-red-600' 
                     : 'bg-transparent text-gray-500 border-gray-300 dark:border-gray-700 hover:border-red-600 hover:text-red-600'
                 }`}
               >
                 <Heart className={`w-3 h-3 ${showFavoritesOnly ? 'fill-white' : ''}`} /> Favorites
               </button>
             )}
          </div>

          <div className="flex items-center gap-3 border-b border-gray-300 dark:border-gray-700 pb-2 focus-within:border-black dark:focus-within:border-white transition-colors w-full md:w-64">
            <Search className="w-4 h-4 text-black dark:text-white" />
            <input 
              type="text" 
              placeholder="SEARCH DISHES" 
              className="outline-none text-sm bg-transparent flex-grow placeholder:text-gray-500 font-medium tracking-wide text-black dark:text-white"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* Categories */}
      <div className="flex flex-wrap gap-4">
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className={`px-6 py-2 text-sm font-bold uppercase tracking-widest transition-all border ${
              activeCategory === cat 
                ? 'bg-black dark:bg-white text-white dark:text-black border-black dark:border-white' 
                : 'bg-white dark:bg-black text-gray-500 dark:text-gray-500 border-gray-200 dark:border-gray-800 hover:border-black dark:hover:border-white hover:text-black dark:hover:text-white'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Grid */}
      {filteredItems.length > 0 ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-12">
          {filteredItems.map(item => (
            <MenuItemCard 
              key={item.id} 
              item={item} 
              isFavorite={userFavorites.has(item.id)}
              onToggleFavorite={toggleFavoriteLocal}
            />
          ))}
        </div>
      ) : (
        <div className="text-center py-32 border border-dashed border-gray-300 dark:border-gray-800">
            <>
              <p className="text-black dark:text-white font-serif text-2xl italic">No dishes found.</p>
              <p className="text-gray-500 mt-2 text-sm">Try adjusting your filters.</p>
              <button 
                onClick={() => { setActiveCategory('all'); setSearchQuery(''); setShowVegOnly(false); setShowFavoritesOnly(false); }}
                className="mt-6 text-xs font-bold uppercase tracking-widest border-b border-black dark:border-white pb-1 hover:text-gray-500 hover:border-gray-500 transition-colors"
              >
                Clear all filters
              </button>
            </>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MenuItem } from '../types';
import { Sparkles, X, Send, User, Loader2 } from 'lucide-react';

interface AIChatProps {
  menuItems: MenuItem[];
}

interface Message {
  role: 'user' | 'model';
  text: string;
}

export const AIChat: React.FC<AIChatProps> = ({ menuItems }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: "Welcome to Noir. I know the menu by heart. What are you in the mood for?" }
  ]);
  const [input, setInput] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isThinking) return;

    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput('');
    setIsThinking(true);

    try {
      // Prepare context about the menu
      const menuContext = menuItems.map(item => 
        `${item.name} (${item.category}): ₹${item.price}. ${item.description}. ${item.isVegetarian ? 'Veg' : 'Non-Veg'}. ${item.fitnessGoal || ''}. ${!item.isAvailable ? '[SOLD OUT]' : ''}`
      ).join('\n');

      const systemPrompt = `You are the concierge for 'Noir Canteen'. 
      Your tone is sophisticated, minimalist, and helpful.
      Here is the current menu status:
      ${menuContext}

      Rules:
      1. Only recommend items from the list above.
      2. If a user asks for something not on the menu, politely suggest a similar alternative.
      3. Keep answers short (max 2 sentences).
      4. Mention price when recommending.
      5. Don't recommend sold-out items unless asked specifically.
      `;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // We combine system prompt and history for a simple stateless request (or use chat session)
      // For this implementation, we'll do a single turn with context to save tokens/complexity, 
      // but feeding previous 2 messages for continuity.
      const recentHistory = messages.slice(-2).map(m => `${m.role === 'user' ? 'Customer' : 'You'}: ${m.text}`).join('\n');

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `${systemPrompt}\n\nConversation History:\n${recentHistory}\nCustomer: ${userMsg}\nYou:`,
      });

      const reply = response.text || "I apologize, I'm having trouble connecting to the kitchen.";

      setMessages(prev => [...prev, { role: 'model', text: reply }]);
    } catch (error) {
      console.error(error);
      setMessages(prev => [...prev, { role: 'model', text: "Connection interruption. Please try again." }]);
    } finally {
      setIsThinking(false);
    }
  };

  return (
    <>
      {/* Trigger Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`fixed bottom-6 right-6 z-50 p-4 rounded-full shadow-2xl transition-all duration-300 hover:scale-110 ${isOpen ? 'rotate-90 bg-white text-black' : 'bg-black text-white dark:bg-white dark:text-black'}`}
      >
        {isOpen ? <X className="w-6 h-6" /> : <Sparkles className="w-6 h-6" />}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-24 right-6 z-50 w-80 md:w-96 bg-white dark:bg-zinc-900 border border-gray-200 dark:border-zinc-800 shadow-2xl rounded-2xl overflow-hidden flex flex-col animate-slide-in origin-bottom-right max-h-[500px]">

          {/* Header */}
          <div className="bg-black dark:bg-white p-4 flex items-center gap-3">
            <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
            <span className="font-serif font-bold text-white dark:text-black">Noir Concierge</span>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50 dark:bg-black">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${msg.role === 'user' ? 'bg-gray-200 dark:bg-zinc-800' : 'bg-black dark:bg-white text-white dark:text-black'}`}>
                  {msg.role === 'user' ? <User className="w-4 h-4 text-gray-600 dark:text-gray-400" /> : <Sparkles className="w-4 h-4" />}
                </div>
                <div className={`p-3 text-sm max-w-[80%] rounded-2xl ${
                  msg.role === 'user' 
                    ? 'bg-white dark:bg-zinc-900 border border-gray-200 dark:border-zinc-800 text-black dark:text-white rounded-tr-none' 
                    : 'bg-black dark:bg-white text-white dark:text-black rounded-tl-none'
                }`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isThinking && (
              <div className="flex gap-3">
                 <div className="w-8 h-8 rounded-full bg-black dark:bg-white flex items-center justify-center">
                    <Sparkles className="w-4 h-4 text-white dark:text-black" />
                 </div>
                 <div className="bg-black dark:bg-white p-4 rounded-2xl rounded-tl-none">
                    <Loader2 className="w-4 h-4 animate-spin text-white dark:text-black" />
                 </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input */}
          <form onSubmit={handleSend} className="p-2 bg-white dark:bg-zinc-900 border-t border-gray-100 dark:border-zinc-800">
            <div className="relative">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask for recommendations..."
                className="w-full bg-gray-100 dark:bg-black border-none rounded-full py-3 pl-4 pr-12 text-sm focus:ring-1 focus:ring-black dark:focus:ring-white outline-none dark:text-white transition-all"
              />
              <button 
                type="submit" 
                disabled={!input.trim() || isThinking}
                className="absolute right-1 top-1 p-2 bg-black dark:bg-white text-white dark:text-black rounded-full hover:opacity-80 disabled:opacity-50 transition-all"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
          </form>
        </div>
      )}
    </>
  );
};

payload.text:
This is a significant architectural change.

Currently, your application is **Serverless**. The React frontend talks directly to Firebase Firestore using Google's pre-built SDKs.

To use MongoDB, you must switch to a **Client-Server Architecture** (specifically the **MERN Stack**: MongoDB, Express, React, Node.js). You cannot access MongoDB directly from the React frontend securely; you need to build a custom backend API to sit in the middle.

Here is the step-by-step guide and the code you would need to write to achieve this.

### Phase 1: The Architectural Shift

1.  **Current (Firebase):** React App ↔ Firebase SDK ↔ Firestore DB
2.  **New (MongoDB):** React App ↔ **Your Node API** ↔ Mongoose ↔ MongoDB

### Phase 2: Create the Backend (New Project Folder)

You need to create a folder (e.g., `/server`) and initialize a Node.js project.

**1. Install Backend Dependencies:**
`npm install express mongoose cors dotenv firebase-admin`

**2. Create the Server (`server/index.js`):**
This server acts as the bridge. It accepts requests from your React app and talks to MongoDB.

```javascript
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');
require('dotenv').config();

const app = express();
app.use(cors());
app.use(express.json());

// Connect to MongoDB
mongoose.connect(process.env.MONGO_URI)
  .then(() => console.log('MongoDB Connected'))
  .catch(err => console.log(err));

// Define a Schema (e.g., for Menu Items)
const MenuItemSchema = new mongoose.Schema({
  name: String,
  price: Number,
  category: String,
  isAvailable: Boolean,
  // ... other fields
});

const MenuItem = mongoose.model('MenuItem', MenuItemSchema);

// API Routes
app.get('/api/menu', async (req, res) => {
  const items = await MenuItem.find({ isAvailable: true });
  res.json(items);
});

app.post('/api/orders', async (req, res) => {
  // Logic to save order to MongoDB
});

app.listen(5000, () => console.log('Server running on port 5000'));
```

### Phase 3: Modify the Frontend (React)

You must rewrite `services/firestoreService.ts` to stop using Firebase SDKs and start using `fetch` or `axios` to call your new server.

**Example: `services/firestoreService.ts` (Refactored)**

```typescript
// OLD (Firebase)
// export const getMenuItems = async () => {
//   const q = query(collection(db, 'menuItems')...);
//   return getDocs(q);
// }

// NEW (MongoDB via API)
const API_URL = "http://localhost:5000/api";

export const getMenuItems = async (): Promise<MenuItem[]> => {
  try {
    const response = await fetch(`${API_URL}/menu`);
    if (!response.ok) throw new Error('Failed to fetch');
    return await response.json();
  } catch (error) {
    console.error(error);
    return [];
  }
};
```

### Phase 4: Handle Authentication

You can keep using Firebase Auth on the frontend, but your new Node backend needs to verify the user is legitimate.

1.  Frontend sends the Firebase ID Token to your backend.
2.  Backend uses `firebase-admin` to verify the token.

**Frontend:**
```typescript
const token = await user.getIdToken();
await fetch(`${API_URL}/orders`, {
  headers: { 'Authorization': `Bearer ${token}` }
});
```

**Backend (`server/index.js`):**
```javascript
const admin = require('firebase-admin');
// Verify token middleware
const verifyToken = async (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  try {
    const decodedToken = await admin.auth().verifyIdToken(token);
    req.user = decodedToken;
    next();
  } catch (e) {
    res.status(401).send('Unauthorized');
  }
};
```

### Phase 5: Real-time Data

**The Biggest Loss:** Firebase gives you real-time updates (`onSnapshot`) out of the box. MongoDB does not do this easily for the frontend.

To restore the "Live Order Status" or "Kitchen Dashboard" features, you would need to:
1.  Implement **Socket.io** on your Node server.
2.  Emit events whenever an order is saved to MongoDB.
3.  Listen for events in your React components.

### Summary Checklist to Migrate

1.  [ ] Set up a **MongoDB Atlas** account (Cloud Database).
2.  [ ] Create a **Node.js/Express** backend project.
3.  [ ] Define **Mongoose Schemas** matching your TypeScript interfaces (`MenuItem`, `Order`, `User`).
4.  [ ] Rewrite `services/firestoreService.ts` entirely to use `fetch()` calls to your backend.
5.  [ ] Implement **Socket.io** if you want real-time features.
6.  [ ] Deploy your backend to a service like Render, Heroku, or DigitalOcean (Vite only hosts the frontend).

**Recommendation:**
Unless you have a specific requirement for relational data linking or strict enterprise constraints, **Firebase is generally better suited for this specific Canteen application** because the Real-time Database features (for the kitchen display) and Auth integration are built-in, saving you hundreds of lines of backend code.

