                       {item.fitnessGoal === 'weight_loss' && (
                         <span className="flex items-center text-xs text-green-600 dark:text-green-400 font-bold uppercase">
                           <Scale className="w-3 h-3 mr-1" /> Weight Loss
                         </span>
